  var CRESCO_LOGO_RATIO = 0.2633; // height / width
  // EDIT PER CLIENT: replace this with the new client's own square icon logo
  // (see generate_logo.py in this package for a quick way to make one).
  var LOGO_ICON_DATA_URI = 'data:image/png;base64,';
  // EDIT PER CLIENT: this client's own corporate colour (RGB), used to brand the
  // HR/utilisation report PDF (cover banner, headings, table headers, charts).
  var CLIENT_COLOR_RGB = [191,30,46]; // LTP Enterprise Pte Ltd - sampled from the LTP logo; confirm/replace with their official brand colour if different.
  // Cresco's own corporate colour (RGB) - stays the same for every client, used
  // only on the Cresco-branded annual invoice (alongside CRESCO_LOGO_DATA_URI).
  var CRESCO_COLOR_RGB = [255,9,46]; // sampled from the Cresco logo

