  function renderUserHistory(){
    var claims = STATE.claims.slice();
    var filter = STATE.historyFilter||'all';
    if(filter!=='all') claims = claims.filter(function(c){ return claimDisplayStatus(c)===filter; });
    var searchQuery = STATE.historySearchQuery||'';
    claims = claims.filter(function(c){ return claimMatchesSearch(c, searchQuery, false); });
    claims.sort(function(a,b){ return b.submitted_at.localeCompare(a.submitted_at); });
    var filters = ['all','pending','approved','reimbursed','rejected'];
    return '<div class="card">'+cardTitleWithClose('Transaction History')+
      '<div class="muted small" style="margin-bottom:12px;">Pending and rejected claims can be edited or deleted. Approved claims are locked.</div>'+
      '<input type="text" id="history-search-input" class="search-input" placeholder="Search by category, vendor, currency or status..." value="'+escapeHtml(searchQuery)+'" style="margin-bottom:12px;" />'+
      '<div class="filter-row">'+filters.map(function(f){ return '<button class="chip-filter '+(filter===f?'active':'')+'" data-action="filter-history" data-filter="'+f+'">'+(f.charAt(0).toUpperCase()+f.slice(1))+'</button>'; }).join('')+'</div>'+
      renderClaimsTable(claims,false,false,true)+
    '</div>';
  }

  function renderUserNotifications(){
    var notifs = STATE.notifications.slice().sort(function(a,b){ return b.created_at.localeCompare(a.created_at); });
    if(!notifs.length) return '<div class="card">'+cardTitleWithClose('Notifications')+'<div class="empty-state">No notifications yet.</div></div>';
    return '<div class="card">'+cardTitleWithClose('Notifications')+'<div class="notif-list">'+
      notifs.map(function(n){
        return '<div class="notif-item '+(n.read?'':'unread')+'"><div>'+escapeHtml(n.message)+'</div>'+
          '<div class="tiny muted">'+fmtDateTime(n.created_at)+'</div>'+
          (!n.read ? '<button class="link-btn" data-action="mark-read" data-id="'+n.id+'">Mark as read</button>' : '')+
        '</div>';
      }).join('')+
    '</div></div>';
  }

  /* =========================================================
     SHARED: CLAIMS TABLE
  ========================================================== */
  // A claim stays "approved" in the database for ever (balances, reports and
  // invoices all read that), but once an admin has ticked it on Finance >
  // Reimbursement it DISPLAYS as "Reimbursed".
  function claimDisplayStatus(c){ return (c.status==='approved' && c.reimbursed_at) ? 'reimbursed' : c.status; }
  function statusPillHtml(c){
    var ds = claimDisplayStatus(c);
    var sub = '';
    if(ds==='rejected' && c.reject_reason) sub = '<div class="tiny muted">'+escapeHtml(c.reject_reason)+'</div>';
    else if(ds==='approved') sub = '<div class="tiny muted">awaiting reimbursement</div>';
    else if(ds==='reimbursed') sub = '<div class="tiny status-reimbursed-date">'+fmtDate(sgDateStrOf(c.reimbursed_at))+'</div>';
    return '<span class="status-pill status-'+ds+'">'+ds+'</span>'+sub;
  }
  // The scheduled reimbursement date. A pending claim whose date has already
  // gone by gets a fresh one the moment it is approved (database rule), so
  // there is nothing meaningful to show yet.
  function reimburseDateCell(c){
    if(c.status==='rejected' || !c.payout_date) return '-';
    if(c.status==='pending' && c.payout_date < sgTodayStr()) return '<span class="tiny muted">Set on approval</span>';
    var t = fmtDate(c.payout_date);
    return c.status==='pending' ? '<span class="muted">'+t+'</span>' : t;
  }

  function renderClaimsTable(claims, showEmployee, adminActions, userActions){
    if(!claims.length) return '<div class="empty-state">No submissions found.</div>';
    var colCount = 10 + (showEmployee?1:0) + (adminActions?1:0) + (userActions?1:0);
    var rows = claims.map(function(c){
      var row = '<tr>'+
        (showEmployee ? '<td>'+escapeHtml(employeeName(c.employee_id))+'</td>' : '')+
        '<td>'+claimantLabel(c)+'</td>'+
        '<td>'+escapeHtml(c.category)+'</td>'+
        '<td>'+escapeHtml(c.vendor||'-')+'</td>'+
        '<td>'+fmtCurrencyAmount(c.currency, c.amount)+((c.currency && c.currency!=='SGD') ? '<div class="tiny muted">\u2248 '+fmtMoney(sgdAmountOf(c))+' SGD</div>' : '')+'</td>'+
        '<td>'+fmtDate(c.receipt_date)+'</td>'+
        '<td>'+fmtDate((c.submitted_at||'').slice(0,10))+'</td>'+
        '<td>'+(c.status==='approved' ? fmtDate((c.decided_at||'').slice(0,10)) : '-')+'</td>'+
        '<td>'+reimburseDateCell(c)+'</td>'+
        '<td>'+statusPillHtml(c)+'</td>'+
        '<td>'+(c.receipt_path ? '<button class="link-btn" data-action="view-receipt" data-id="'+c.id+'">View</button>' : '-')+'</td>'+
        (adminActions ? (c.status==='pending' ? renderApprovalActions(c) : '<td> - </td>') : '')+
        (userActions ? renderUserActionsCell(c) : '')+
      '</tr>';
      var expandRow = '';
      if(adminActions && STATE.rejectingClaimId===c.id){
        expandRow = '<tr class="reject-row"><td colspan="'+colCount+'">'+renderRejectPanel(c)+'</td></tr>';
      } else if(userActions && STATE.editingClaimId===c.id){
        expandRow = '<tr class="reject-row"><td colspan="'+colCount+'">'+renderClaimEditPanel(c)+'</td></tr>';
      }
      return row+expandRow;
    }).join('');
    return '<div class="table-wrap"><table class="data-table"><thead><tr>'+
      (showEmployee?'<th>Employee</th>':'')+
      '<th>Claiming For</th><th>Category</th><th>Vendor</th><th>Amount</th><th>Receipt Date</th><th>Submission Date</th><th>Approved</th><th>Reimburse Date</th><th>Status</th><th>Receipt</th>'+
      (adminActions?'<th>Actions</th>':'')+
      (userActions?'<th>Actions</th>':'')+
    '</tr></thead><tbody>'+rows+'</tbody></table></div>';
  }

  function renderApprovalActions(c){
    return '<td class="actions-cell">'+
      '<button class="btn btn-sm btn-success" data-action="approve-claim" data-id="'+c.id+'">Approve</button>'+
      '<button class="btn btn-sm btn-danger" data-action="start-reject" data-id="'+c.id+'">Reject</button>'+
    '</td>';
  }

  function renderUserActionsCell(c){
    if(STATE.confirmDeleteClaimId===c.id){
      return '<td class="actions-cell">'+
        '<button class="btn btn-sm btn-danger" data-action="delete-claim-confirm" data-id="'+c.id+'">Confirm?</button> '+
        '<button class="btn btn-sm btn-ghost" data-action="delete-claim-cancel" data-id="'+c.id+'">Cancel</button>'+
      '</td>';
    }
    if(c.status==='pending' || c.status==='rejected'){
      return '<td class="actions-cell">'+
        '<button class="btn btn-sm btn-ghost" data-action="start-edit-claim" data-id="'+c.id+'">Edit</button> '+
        '<button class="btn btn-sm btn-danger" data-action="delete-claim" data-id="'+c.id+'">Delete</button>'+
      '</td>';
    }
    return '<td> - </td>';
  }

  function renderRejectPanel(c){
    return '<div class="reject-panel">'+
      '<label>Rejection Reason<select data-field="reject-reason-'+c.id+'" data-action="reject-reason-select" data-id="'+c.id+'"><option value="">Select a reason...</option>'+
        STATE.rejectReasons.filter(function(r){ return r!=='Others'; }).map(function(r){ return '<option value="'+escapeHtml(r)+'">'+escapeHtml(r)+'</option>'; }).join('')+
        '<option value="Others">Others (please specify)</option>'+
      '</select></label>'+
      '<label id="reject-other-wrap-'+c.id+'" style="display:none;">Please Specify<input type="text" data-field="reject-other-'+c.id+'" placeholder="Type the reason..." /></label>'+
      '<label>Additional Note (optional)<input type="text" data-field="reject-note-'+c.id+'" placeholder="Add more detail..." /></label>'+
      '<div class="reject-actions">'+
        '<button class="btn btn-sm btn-danger" data-action="confirm-reject" data-id="'+c.id+'">Confirm Reject</button>'+
        '<button class="btn btn-sm btn-ghost" data-action="cancel-reject" data-id="'+c.id+'">Cancel</button>'+
      '</div></div>';
  }

  function renderClaimEditPanel(c){
    var myFamily = myFamilyMembers();
    return '<div class="reject-panel">'+
      (myFamily.length ? (
      '<label>Claiming For<select id="edit-family-'+c.id+'"><option value="" '+(!c.family_member_id?'selected':'')+'>Self ('+escapeHtml(STATE.profile.name)+')</option>'+
        myFamily.map(function(m){ return '<option value="'+m.id+'" '+(c.family_member_id===m.id?'selected':'')+'>'+escapeHtml(m.name)+' ('+escapeHtml(m.relationship)+')</option>'; }).join('')+
      '</select></label>'
      ) : '')+
      '<label>Benefit Category<select id="edit-category-'+c.id+'">'+
        STATE.benefits.map(function(b){ return '<option value="'+escapeHtml(b)+'" '+(b===c.category?'selected':'')+'>'+escapeHtml(b)+'</option>'; }).join('')+
      '</select></label>'+
      '<label>Vendor / Merchant<input type="text" id="edit-vendor-'+c.id+'" list="vendor-options-'+c.id+'" value="'+escapeHtml(c.vendor||'')+'" autocomplete="off"/></label>'+
      renderVendorDatalist('vendor-options-'+c.id)+
      '<label>Currency<select id="edit-currency-'+c.id+'">'+renderCurrencyOptions(c.currency)+'</select></label>'+
      '<label>Amount<input type="number" id="edit-amount-'+c.id+'" step="0.01" min="0.01" value="'+c.amount+'"/></label>'+
      '<div id="edit-amount-preview-'+c.id+'" class="tiny muted"></div>'+
      '<div id="edit-amount-live-error-'+c.id+'" class="field-error" style="display:none;"></div>'+
      '<label>Receipt Date<input type="date" id="edit-date-'+c.id+'" value="'+c.receipt_date+'" min="'+yearStartStr()+'" max="'+todayStr()+'"/></label>'+
      '<div class="field-hint">Only receipts from '+fmtDateDMY(yearStartStr())+' onward can be claimed this cycle - your benefits reset every '+benefitYearResetLabel()+'.</div>'+
      '<label>Replace Receipt (optional)</label>'+
      '<div class="dropzone" id="edit-receipt-dropzone-'+c.id+'">'+
        '<input type="file" id="edit-receipt-'+c.id+'" accept="image/*,.pdf"/>'+
        '<div class="dropzone-hint">Choose a file, or drag and drop it here</div>'+
      '</div>'+
      (STATE.claimFormError ? '<div class="field-error">'+escapeHtml(STATE.claimFormError)+'</div>' : '')+
      (c.status==='rejected' ? '<div class="field-hint">Saving will resubmit this claim for review.</div>' : '')+
      '<div class="reject-actions">'+
        '<button class="btn btn-sm btn-primary" data-action="confirm-edit-claim" data-id="'+c.id+'">Save Changes</button>'+
        '<button class="btn btn-sm btn-ghost" data-action="cancel-edit-claim" data-id="'+c.id+'">Cancel</button>'+
      '</div></div>';
  }

  /* =========================================================
     ADMIN MODULE ACCESS
     profiles.admin_modules lists the modules an admin may use; NULL (or the
     column not existing yet, before migration 018) means full access. This
     only decides what the screens SHOW - the sensitive Reimbursement actions
     and changes to roles / module access are also enforced in the database
     (migration 018).
  ========================================================== */
  var ADMIN_MODULES = [
    {key:'approvals',     label:'Pending Approvals'},
    {key:'all',           label:'All Submissions'},
    {key:'staff',         label:'Employee Management'},
    {key:'benefits',      label:'Benefit Categories'},
    {key:'access',        label:'User Access'},
    {key:'finance',       label:'Finance - Invoicing'},
    {key:'reimbursement', label:'Finance - Reimbursement'},
    {key:'reports',       label:'Reports'}
  ];
  // The logged-in admin's own profile, preferring the freshly loaded list (so
  // a change made on User Access takes effect straight away) over the copy
  // read at login.
  function ownAdminProfile(){
    var id = STATE.session && STATE.session.user && STATE.session.user.id;
    return (id && profileById(id)) || STATE.profile;
  }
  function adminHasModule(key){
    var p = ownAdminProfile();
    if(!p || p.role!=='admin') return false;
    var m = p.admin_modules;
    return !m || m.indexOf(key)!==-1;
  }
  function adminAccessSummary(p){
    var m = p.admin_modules;
    return (!m) ? 'Full access' : (m.length+' of '+ADMIN_MODULES.length+' modules');
  }

  /* =========================================================
     ADMIN MODULE
  ========================================================== */
  function renderAdminShell(){
    var can = adminHasModule;
    var pendingCount = can('approvals') ? STATE.claims.filter(function(c){ return c.status==='pending'; }).length : 0;
    // The Finance tab badge only nags once utilisation has actually hit 80%
    // (entitlementCushionStatus().reminderCount) - not merely whenever
    // something is technically un-invoiced, which is normal and fine as
    // long as the float hasn't run down that far.
    // Combines the distinct reasons Finance needs a look - items awaiting
    // invoicing (utilisation-triggered), invoices already issued but not yet
    // marked paid, and approved claims whose reimbursement date has arrived
    // - into one top-nav count; the sub-tab badges break them back out.
    // Each part only counts for an admin who can actually open it.
    var financeReminderCount =
      (can('finance') ? (entitlementCushionStatus().reminderCount + unpaidEntitlementInvoices().length) : 0) +
      (can('reimbursement') ? reimbursementDueClaims().length : 0);
    var navDefs = [
      {key:'approvals', show:can('approvals'),  label:'Pending Approvals'+(pendingCount?' <span class="badge">'+pendingCount+'</span>':'')},
      {key:'all',       show:can('all'),        label:'All Submissions'},
      {key:'staff',     show:can('staff'),      label:'Employee Management'},
      {key:'benefits',  show:can('benefits'),   label:'Benefit Categories'},
      {key:'access',    show:can('access'),     label:'User Access'},
      {key:'finance',   show:(can('finance')||can('reimbursement')), label:'Finance'+(financeReminderCount?' <span class="badge">'+financeReminderCount+'</span>':'')},
      {key:'reports',   show:can('reports'),    label:'Reports'}
    ].filter(function(d){ return d.show; });
    var allowedKeys = navDefs.map(function(d){ return d.key; });
    // If the open tab isn't (or is no longer) allowed - e.g. access was just
    // changed - fall back to the first one that is.
    if(allowedKeys.indexOf(STATE.activeTab)===-1){ STATE.activeTab = allowedKeys[0] || null; }
    var tab = STATE.activeTab;
    return '<div class="shell">'+renderTopbar()+
      (can('finance') ? renderMoneyHoldingBanner() : '')+
      renderActionItemsBanner()+
      '<div class="tabs">'+navDefs.map(function(d){ return navTab(d.key, d.label); }).join('')+'</div>'+
      '<div class="content">'+
        (!tab ? '<div class="card"><div class="empty-state">Your account is an administrator but has no modules switched on. Ask an administrator with User Access to enable the ones you need.</div></div>' :
         tab==='all' ? renderAdminAllSubmissions() :
         tab==='staff' ? renderAdminStaff() :
         tab==='benefits' ? renderAdminBenefits() :
         tab==='access' ? renderAdminAccess() :
         tab==='finance' ? renderAdminFinanceModule() :
         tab==='reports' ? renderAdminReports() :
         renderAdminApprovals())+
      '</div></div>';
  }

  // Finance module: Annual Invoice, New Hire Invoicing and Invoice History
  // are all facets of the same billing workflow, so they live under one
  // top-level "Finance" tab with their own sub-tab row, rather than
  // crowding the main nav with three separate top-level tabs.
  function renderAdminFinanceModule(){
    var canInvoice = adminHasModule('finance'), canReimburse = adminHasModule('reimbursement');
    var allowedSubs = (canInvoice ? ['annual','newhire','history'] : []).concat(canReimburse ? ['reimbursement'] : []);
    var sub = (STATE.financeSubTab && allowedSubs.indexOf(STATE.financeSubTab)!==-1) ? STATE.financeSubTab : allowedSubs[0];
    if(!sub){ return '<div class="card"><div class="empty-state">No Finance modules are switched on for your account.</div></div>'; }
    var reminderCount = canInvoice ? entitlementCushionStatus().reminderCount : 0;
    var unpaidCount = canInvoice ? unpaidEntitlementInvoices().length : 0;
    var reimbDueCount = canReimburse ? reimbursementDueClaims().length : 0;
    var subTabBtn = function(key, label){
      return '<button class="tab '+(sub===key?'active':'')+'" data-action="finance-subtab" data-subtab="'+key+'">'+label+'</button>';
    };
    var clientSetupStrip = STATE.editingBenefitYearStart
      ? ('<div class="field-hint" style="margin-bottom:14px;">Client Setup &middot; Benefit Year starts: <select id="benefit-year-start-input">'+REPORT_MONTH_NAMES.map(function(mn,i){ return '<option value="'+(i+1)+'" '+((i+1)===benefitYearStartMonth()?'selected':'')+'>'+mn+'</option>'; }).join('')+'</select> <button class="btn btn-sm btn-primary" data-action="save-benefit-year-start">Save</button></div>')
      : ('<div class="field-hint" style="margin-bottom:14px;">Client Setup &middot; Benefit Year starts: '+REPORT_MONTH_NAMES[benefitYearStartMonth()-1]+' <button class="link-btn" data-action="edit-benefit-year-start">Edit</button></div>');
    return (canInvoice ? clientSetupStrip : '')+
      '<div class="tabs" style="margin-bottom:16px;">'+
        (canInvoice ? (subTabBtn('annual','Annual Invoice')+
          subTabBtn('newhire','New Hire Invoicing'+(reminderCount?' <span class="badge">'+reminderCount+'</span>':''))+
          subTabBtn('history','Invoice History'+(unpaidCount?' <span class="badge">'+unpaidCount+'</span>':''))) : '')+
        (canReimburse ? subTabBtn('reimbursement','Reimbursement'+(reimbDueCount?' <span class="badge">'+reimbDueCount+'</span>':'')) : '')+
      '</div>'+
      (sub==='newhire' ? renderAdminNewHireInvoicing() :
       sub==='history' ? renderAdminInvoiceHistory() :
       sub==='reimbursement' ? renderAdminReimbursement() :
       renderAdminFinance());
  }

  function renderAdminApprovals(){
    var pending = STATE.claims.filter(function(c){ return c.status==='pending'; }).sort(function(a,b){ return a.submitted_at.localeCompare(b.submitted_at); });
    return '<div class="card"><div class="card-title">Pending Approvals'+(pending.length?' <span class="badge">'+pending.length+'</span>':'')+'</div>'+renderClaimsTable(pending,true,true,false)+'</div>';
  }

  function renderAdminAllSubmissions(){
    var searchQuery = STATE.allSubmissionsSearchQuery||'';
    var claims = STATE.claims.filter(function(c){ return claimMatchesSearch(c, searchQuery, true); }).slice().sort(function(a,b){ return b.submitted_at.localeCompare(a.submitted_at); });
    return '<div class="card"><div class="card-title">All Submissions</div>'+
      '<input type="text" id="all-submissions-search-input" class="search-input" placeholder="Search by employee, category, vendor, currency or status..." value="'+escapeHtml(searchQuery)+'" style="margin-bottom:12px;" />'+
      renderClaimsTable(claims,true,false,false)+'</div>';
  }

  var RELATIONSHIP_OPTIONS = ['Spouse','Child','Parent','Other'];
  function relationshipOptionsHtml(){
    return RELATIONSHIP_OPTIONS.map(function(r){ return '<option value="'+r+'">'+r+'</option>'; }).join('');
  }

  function familyDraftRowHtml(){
    return '<div class="family-draft-row" style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;width:100%;margin-bottom:10px;padding-bottom:10px;border-bottom:1px dashed var(--border);">'+
      '<label class="mini-field">Family Member Name<input type="text" name="famName[]" placeholder="e.g. Mary Lim" /></label>'+
      '<label class="mini-field">Relationship<select name="famRelationship[]"><option value="">Select...</option>'+relationshipOptionsHtml()+'</select></label>'+
      '<label class="mini-field">Date of Birth<input type="date" name="famDob[]" style="width:160px" /></label>'+
      '<label class="mini-field">NRIC<input type="text" name="famNric[]" placeholder="e.g. T0123456A" style="width:140px" /></label>'+
      '<button type="button" class="btn btn-sm btn-ghost" data-action="remove-family-draft-row">Remove</button>'+
    '</div>';
  }

  function renderFamilyExpandPanel(p, myFamily){
    var rows = myFamily.map(function(m){
      var actionsCell = STATE.confirmDeleteFamilyId===m.id
        ? '<button class="btn btn-sm btn-danger" data-action="delete-family-confirm" data-id="'+m.id+'">Confirm?</button> <button class="btn btn-sm btn-ghost" data-action="delete-family-cancel">Cancel</button>'
        : '<button class="btn btn-sm btn-danger" data-action="delete-family" data-id="'+m.id+'">Remove</button>';
      return '<tr><td>'+escapeHtml(m.name)+'</td><td>'+escapeHtml(m.relationship)+'</td><td>'+fmtDate(m.date_of_birth)+'</td><td>'+escapeHtml(m.nric||'-')+'</td><td class="actions-cell">'+actionsCell+'</td></tr>';
    }).join('');
    var addForm = STATE.addingFamilyForEmployeeId===p.id
      ? '<form data-form="add-family-inline" class="inline-form" style="margin-top:10px;">'+
          '<input type="hidden" name="employeeEmail" value="'+escapeHtml(p.email)+'" />'+
          '<label class="mini-field">Full Name<input type="text" name="name" placeholder="e.g. Mary Lim" required /></label>'+
          '<label class="mini-field">Relationship<select name="relationship" required><option value="">Select...</option>'+relationshipOptionsHtml()+'</select></label>'+
          '<label class="mini-field">Date of Birth<input type="date" name="dateOfBirth" style="width:160px" required /></label>'+
          '<label class="mini-field">NRIC<input type="text" name="nric" placeholder="e.g. T0123456A" style="width:140px" /></label>'+
          '<button type="submit" class="btn btn-sm btn-primary">Save</button> '+
          '<button type="button" class="btn btn-sm btn-ghost" data-action="cancel-add-family-inline">Cancel</button>'+
        '</form>'
      : '<button class="btn btn-sm btn-ghost" data-action="start-add-family-inline" data-id="'+p.id+'">+ Add Family Member</button>';
    return '<div class="reject-panel">'+
      '<div class="card-title" style="font-size:13px;">Family - '+escapeHtml(p.name)+'</div>'+
      (rows ? '<div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Relationship</th><th>Date of Birth</th><th>NRIC</th><th>Actions</th></tr></thead><tbody>'+rows+'</tbody></table></div>' : '<div class="muted small">No family members recorded yet.</div>')+
      addForm+
    '</div>';
  }

  function renderAdminStaff(){
    var roleFilter = STATE.staffRoleFilter || 'all';
    var visibleProfiles = STATE.profiles.filter(function(p){ return roleFilter==='all' || p.role===roleFilter; });
    var COL_COUNT = 12;
    var staffRows = visibleProfiles.map(function(p){
      var allocCell;
      // Whether THIS employee's own wallet gets prorated for a partial
      // first year (set at Add Employee time) - editable here too, so it's
      // not stuck as a one-time decision. This is the standing setting the
      // wallet calculation (computeWallet) always follows; it's separate
      // from the one-off "Prorate" override on a specific New Hire
      // Invoicing run, which only affects billing and never this.
      var prorateOn = p.prorate_entitlement_default!==false;
      var prorateCell = '<label class="tiny"><input type="checkbox" data-action="toggle-prorate-default" data-id="'+p.id+'" '+(prorateOn?'checked':'')+'/> '+(prorateOn?'On':'Off')+'</label>';
      if(STATE.promotingEmployeeId===p.id){
        var promoDelta = (STATE.promotionDraftAllocation||0) - (Number(p.annual_allocation)||0);
        allocCell = '<div style="min-width:260px;">'+
          '<div class="tiny muted" style="margin-bottom:4px;">'+fmtMoney(p.annual_allocation)+' &rarr; '+fmtMoney(STATE.promotionDraftAllocation)+' ('+(promoDelta>=0?'+':'-')+fmtMoney(Math.abs(promoDelta))+')</div>'+
          '<label class="mini-field">Effective Date<input type="date" id="promotion-date-input-'+p.id+'" value="'+(STATE.promotionDraftDate||'')+'" style="width:150px"/></label> '+
          '<button class="btn btn-sm btn-primary" data-action="confirm-promotion" data-id="'+p.id+'">Confirm</button> '+
          '<button class="btn btn-sm btn-ghost" data-action="cancel-promotion" data-id="'+p.id+'">Cancel</button>'+
          '<div class="tiny muted" style="margin-top:4px;">This '+(promoDelta>=0?'increase':'decrease')+' will show up on New Hire Invoicing for billing from the effective date above.</div>'+
        '</div>';
      } else {
        allocCell = STATE.editingAllocId===p.id
          ? '<input type="number" min="0" step="1" style="width:90px" id="alloc-input-'+p.id+'" value="'+p.annual_allocation+'"/> <button class="btn btn-sm btn-primary" data-action="save-alloc" data-id="'+p.id+'">Save</button>'
          : fmtMoney(p.annual_allocation)+' <button class="link-btn" data-action="edit-alloc" data-id="'+p.id+'">Edit</button>';
      }
      var terminationCell = STATE.editingTerminationId===p.id
        ? '<input type="date" style="width:150px" id="termination-input-'+p.id+'" value="'+(p.date_of_termination||'')+'"/> <button class="btn btn-sm btn-primary" data-action="save-termination" data-id="'+p.id+'">Save</button>'
        : (p.date_of_termination ? fmtDate(p.date_of_termination) : '-')+' <button class="link-btn" data-action="edit-termination" data-id="'+p.id+'">Edit</button>';
      var actionsCell;
      if(STATE.confirmDeactivateId===p.id){
        actionsCell = '<button class="btn btn-sm btn-danger" data-action="toggle-active-confirm" data-id="'+p.id+'">Confirm?</button> <button class="btn btn-sm btn-ghost" data-action="toggle-active-cancel" data-id="'+p.id+'">Cancel</button>';
      } else if(STATE.confirmDeleteProfileId===p.id){
        actionsCell = '<button class="btn btn-sm btn-danger" data-action="delete-profile-confirm" data-id="'+p.id+'">Confirm Delete?</button> <button class="btn btn-sm btn-ghost" data-action="delete-profile-cancel" data-id="'+p.id+'">Cancel</button>';
      } else {
        actionsCell = '<button class="btn btn-sm btn-ghost" data-action="toggle-active" data-id="'+p.id+'">'+(p.active?'Deactivate':'Activate')+'</button> '+
          '<button class="btn btn-sm btn-danger" data-action="delete-profile" data-id="'+p.id+'">Delete</button>';
      }
      var roleLabel = p.role==='admin' ? 'Admin' : 'User';
      var myFamily = STATE.familyMembers.filter(function(m){ return m.employee_email===p.email; });
      var isExpanded = STATE.expandedFamilyEmployeeId===p.id;
      var familyCell = '<button class="link-btn" data-action="toggle-family-row" data-id="'+p.id+'">'+
        (myFamily.length ? (myFamily.length+' member'+(myFamily.length>1?'s':'')) : '-')+
        (isExpanded ? ' ▴' : ' ▾')+'</button>';
      // The Status column shouldn't rely solely on the `active` flag - a
      // passed Date of Termination now locks someone out on its own (see
      // loadProfileAndData), so the directory needs to reflect that even
      // when nobody has separately clicked Deactivate for them.
      var isTerminated = p.date_of_termination && p.date_of_termination<=todayStr();
      var statusLabel = isTerminated ? 'Terminated' : (p.active ? 'Active' : 'Inactive');
      var statusClass = (isTerminated || !p.active) ? 'status-rejected' : 'status-approved';
      // Separate from employment Status on purpose - this is about billing
      // (has the client actually paid for this person's entitlement invoice
      // yet), not employment, so it's its own small line rather than folded
      // into the status pill above.
      var paymentFlag = employeeHasUnpaidEntitlementInvoice(p.id)
        ? '<div class="tiny" style="color:var(--danger); margin-top:3px;">&#9679; Payment pending</div>' : '';
      var row = '<tr><td>'+escapeHtml(p.name)+'</td><td>'+escapeHtml(p.email)+'</td><td>'+escapeHtml(p.nric||'-')+'</td>'+
        '<td><span class="role-chip">'+roleLabel+'</span></td>'+
        '<td>'+familyCell+'</td>'+
        '<td>'+allocCell+'</td>'+
        '<td>'+prorateCell+'</td>'+
        '<td>'+fmtDate(p.date_of_joining)+'</td>'+
        '<td>'+(p.effective_date ? fmtDate(p.effective_date) : '-')+'</td>'+
        '<td>'+terminationCell+'</td>'+
        '<td><span class="status-pill '+statusClass+'">'+statusLabel+'</span>'+paymentFlag+'</td>'+
        '<td class="actions-cell">'+actionsCell+'</td></tr>';
      var expandRow = isExpanded ? ('<tr class="reject-row"><td colspan="'+COL_COUNT+'">'+renderFamilyExpandPanel(p, myFamily)+'</td></tr>') : '';
      return row+expandRow;
    }).join('');
    var staffFilters = [{key:'all',label:'All'},{key:'user',label:'User'},{key:'admin',label:'Admin'}];

    var pendingInvites = STATE.invites.filter(function(i){ return !i.used; });
    var inviteRows = pendingInvites.map(function(i){
      var welcomeCell;
      if(i.welcome_email_sent){
        // welcome_email_sent_at wasn't being set by the cron function on
        // older rows (fixed in migration 013) - fall back to a plain "Sent"
        // label so an already-sent invite never gets stuck showing
        // "Scheduled for..." forever.
        welcomeCell = i.welcome_email_sent_at ? fmtDateTime(i.welcome_email_sent_at) : 'Sent';
      } else if(i.effective_date){
        welcomeCell = '<span class="tiny muted">Scheduled for '+fmtDate(i.effective_date)+'</span>';
      } else {
        welcomeCell = '-';
      }
      return '<tr><td>'+escapeHtml(i.name)+'</td><td>'+escapeHtml(i.email)+'</td><td>'+fmtMoney(i.annual_allocation)+'</td>'+
        '<td>'+welcomeCell+'</td>'+
        '<td>'+(i.effective_date ? fmtDate(i.effective_date) : '-')+'</td>'+
        '<td>'+(STATE.confirmRevokeInvite===i.email
          ? '<button class="btn btn-sm btn-danger" data-action="revoke-invite-confirm" data-email="'+escapeHtml(i.email)+'">Confirm?</button> <button class="btn btn-sm btn-ghost" data-action="revoke-invite-cancel">Cancel</button>'
          : '<button class="btn btn-sm btn-ghost" data-action="revoke-invite" data-email="'+escapeHtml(i.email)+'">Revoke</button>')+
        '</td></tr>';
    }).join('');

    var mode = STATE.addEmployeeMode || 'single';
    var byBounds = benefitYearBounds(currentBenefitYear());
    var benefitYearNote = '<div class="field-hint" style="margin-bottom:14px;">Benefit Year runs '+fmtDateDMY(byBounds.startStr)+' - '+fmtDateDMY(byBounds.endStr)+
      ' (starts '+REPORT_MONTH_NAMES[benefitYearStartMonth()-1]+') - Effective Dates and proration below are measured against this cycle.</div>';

    return ''+
    benefitYearNote+
    '<div class="card"><div class="card-title">Add Employee</div>'+
      '<div class="filter-row" style="margin-bottom:12px;">'+
        '<button type="button" class="chip-filter '+(mode==='single'?'active':'')+'" data-action="set-add-employee-mode" data-mode="single">Employee Only</button>'+
        '<button type="button" class="chip-filter '+(mode==='family'?'active':'')+'" data-action="set-add-employee-mode" data-mode="family">Employee + Family</button>'+
      '</div>'+
      '<form data-form="invite-staff" class="inline-form">'+
        '<label class="mini-field">Full Name<input type="text" name="name" placeholder="e.g. Jane Lim" required /></label>'+
        '<label class="mini-field">Work Email<input type="email" name="email" placeholder="jane@company.com" required /></label>'+
        '<label class="mini-field">Date of Employment<input type="date" name="dateOfEmployment" style="width:160px" required /></label>'+
        '<label class="mini-field">Effective Date<input type="date" name="effectiveDate" id="add-emp-effective-date" style="width:160px" required oninput="window.updateAddEmployeeProratePreview()" /></label>'+
        '<label class="mini-field">PayNow Mobile Number<input type="tel" name="paynowMobile" placeholder="e.g. 91234567" style="width:160px" required /></label>'+
        '<label class="mini-field">NRIC<input type="text" name="nric" placeholder="e.g. S1234567A" style="width:140px" /></label>'+
        '<label class="mini-field">Entitlement (SGD)<input type="number" name="annualAllocation" id="add-emp-allocation" value="1000" min="0" step="1" style="width:140px" required oninput="window.updateAddEmployeeProratePreview()" /></label>'+
        '<label class="mini-field" style="flex-basis:100%;flex-direction:row;align-items:center;gap:6px;">'+
          '<input type="checkbox" name="prorateEntitlement" id="add-emp-prorate" checked style="width:auto;" onchange="window.updateAddEmployeeProratePreview()" /> '+
          '<span>Prorate for partial first year</span>'+
        '</label>'+
        '<div class="field-hint" id="add-emp-prorate-preview" style="flex-basis:100%;"></div>'+
        (mode==='family' ? (
          '<div class="field-hint" style="flex-basis:100%;margin-top:4px;">Family members (share this employee\'s entitlement - no separate login or email)</div>'+
          '<div id="family-draft-rows" style="flex-basis:100%;">'+familyDraftRowHtml()+'</div>'+
          '<button type="button" class="btn btn-sm btn-ghost" data-action="add-family-draft-row">+ Add another family member</button>'
        ) : '')+
        '<button type="submit" class="btn btn-primary" style="flex-basis:100%;">'+(mode==='family'?'Add Employee + Family':'Add Employee')+'</button>'+
      '</form>'+
      '<div class="field-hint">New employees are invited as Users. To grant Admin access, use the User Access tab after they\'ve signed up. A welcome email with sign-up instructions is sent automatically once the Effective Date arrives - only one email goes to the employee, family members never get their own.</div>'+
    '</div>'+
    '<div class="card"><div class="card-title">Bulk Upload (CSV)</div>'+
      '<div class="muted small" style="margin-bottom:10px;">One file for both employees and their family. Columns: recordType,name,email,relationship,dateOfBirth,nric,annualAllocation,dateOfEmployment,paynowMobile,effectiveDate. First row is a header and is skipped.<br/>'+
      '<b>Employee</b> row: recordType=Employee, email=their own email, then nric / annualAllocation / dateOfEmployment / paynowMobile / effectiveDate (leave relationship and dateOfBirth blank).<br/>'+
      '<b>Family</b> row: recordType=Family, email=the employee\'s email they belong to, relationship (Spouse/Child/Parent/Other) and dateOfBirth required, nric optional (leave the last four columns blank). List an employee\'s Family rows right under their Employee row - any number is fine.</div>'+
      '<div class="dropzone" id="staff-csv-dropzone">'+
        '<input type="file" id="staff-csv-input" accept=".csv" />'+
        '<div class="dropzone-hint">Choose a file, or drag and drop it here</div>'+
      '</div>'+
    '</div>'+
    (pendingInvites.length ? '<div class="card"><div class="card-title">Pending Employee New User Sign Up</div><div class="table-wrap"><table class="data-table">'+
      '<thead><tr><th>Name</th><th>Email</th><th>Allocation</th><th>Welcome Email Sent</th><th>Effective Date</th><th>Actions</th></tr></thead>'+
      '<tbody>'+inviteRows+'</tbody></table></div></div>' : '')+
    '<div class="card"><div class="card-title">Employee Directory</div>'+
      '<div class="filter-row">'+staffFilters.map(function(f){ return '<button class="chip-filter '+(roleFilter===f.key?'active':'')+'" data-action="filter-staff" data-filter="'+f.key+'">'+f.label+'</button>'; }).join('')+'</div>'+
      '<div class="table-wrap"><table class="data-table">'+
      '<thead><tr><th>Name</th><th>Email</th><th>NRIC</th><th>Role</th><th>Family</th><th>Annual Allocation</th><th>Prorate</th><th>Date of Employment</th><th>Effective Date</th><th>Date of Termination</th><th>Status</th><th>Actions</th></tr></thead>'+
      '<tbody>'+staffRows+'</tbody></table></div>'+
      '<div class="field-hint">The <strong>Prorate</strong> column is this employee\'s standing setting - On means their own wallet shows a reduced amount for a partial first year (matching what New Hire Invoicing normally bills for them); Off means their wallet always shows the full entitlement. It reverts to having no effect automatically from the January after they join. Changing it here does not touch any invoice already issued or in progress.</div>'+
      '<div class="field-hint">Deleting an employee removes their account, all their claim history, and their notifications - permanently, and this cannot be undone. Their login itself still technically exists in Supabase until removed from the dashboard\'s Authentication &gt; Users page too, but they won\'t be able to do anything with it here once deleted.</div>'+
    '</div>';
  }

  function renderAdminBenefits(){
    return '<div class="card"><div class="card-title">Add Benefit Category</div>'+
      '<form data-form="add-benefit" class="inline-form">'+
        '<input type="text" name="category" placeholder="e.g. Wellness" required />'+
        '<button type="submit" class="btn btn-primary">Add Category</button>'+
      '</form></div>'+
      '<div class="card"><div class="card-title">Current Benefit Categories</div>'+
      '<div class="chip-list">'+STATE.benefits.map(function(b){ return '<span class="chip">'+escapeHtml(b)+' <button class="chip-remove" data-action="remove-benefit" data-cat="'+escapeHtml(b)+'">x</button></span>'; }).join('')+'</div>'+
      '<div class="field-hint">Removing a category only affects future claims - historical submissions keep their original category.</div></div>';
  }

  function adminAccessCell(p){
    if(p.role!=='admin') return '<td><span class="tiny muted">&mdash;</span></td>';
    var alerts = [];
    if(p.notify_pending_digest) alerts.push('daily digest');
    if(p.notify_payout_reminder) alerts.push('reimbursement reminder');
    return '<td><div class="tiny"><strong>'+escapeHtml(adminAccessSummary(p))+'</strong></div>'+
      '<div class="tiny muted">'+(alerts.length ? ('Emails: '+alerts.join(', ')) : 'No admin emails')+'</div>'+
      '<button class="link-btn tiny" data-action="edit-admin-settings" data-id="'+p.id+'">Manage</button></td>';
  }
  function renderAdminSettingsPanel(p){
    var d = STATE.adminSettingsDraft;
    var isSelf = STATE.session && STATE.session.user && p.id===STATE.session.user.id;
    var moduleBoxes = ADMIN_MODULES.map(function(m){
      var locked = d.full || (isSelf && m.key==='access');
      return '<label class="admin-check"><input type="checkbox" data-action="admin-module-toggle" data-module="'+m.key+'" '+((d.full||d.modules[m.key])?'checked':'')+' '+(locked?'disabled':'')+'/> '+escapeHtml(m.label)+'</label>';
    }).join('');
    return '<div class="admin-settings-panel">'+
      '<div style="font-weight:700; margin-bottom:8px;">Access &amp; email alerts for '+escapeHtml(p.name)+'</div>'+
      '<label class="admin-check"><input type="checkbox" data-action="admin-full-access" '+(d.full?'checked':'')+'/> <strong>Full access</strong> - every module, including any added in future</label>'+
      '<div class="admin-module-grid">'+moduleBoxes+'</div>'+
      (isSelf ? '<div class="tiny muted" style="margin-bottom:8px;">You can\'t remove your own User Access.</div>' : '')+
      '<div class="tiny muted" style="margin-bottom:4px;">Email alerts</div>'+
      '<label class="admin-check"><input type="checkbox" data-action="admin-notify-digest" '+(d.digest?'checked':'')+'/> Daily pending-claims digest (9am) <span class="tiny muted">- needs Pending Approvals</span></label>'+
      '<label class="admin-check"><input type="checkbox" data-action="admin-notify-reminder" '+(d.reminder?'checked':'')+'/> Reimbursement-day reminder (8am on the 7th, or the next working day) <span class="tiny muted">- needs Reimbursement</span></label>'+
      '<div style="margin-top:12px; display:flex; gap:10px;">'+
        '<button class="btn btn-sm btn-primary" data-action="save-admin-settings">Save</button>'+
        '<button class="btn btn-sm" data-action="cancel-admin-settings">Cancel</button>'+
      '</div>'+
    '</div>';
  }
  function openAdminSettings(id){
    var p = profileById(id); if(!p) return;
    var mods = {};
    ADMIN_MODULES.forEach(function(m){ mods[m.key] = !p.admin_modules || p.admin_modules.indexOf(m.key)!==-1; });
    STATE.adminSettingsDraft = {id:id, full:!p.admin_modules, modules:mods, digest:!!p.notify_pending_digest, reminder:!!p.notify_payout_reminder};
    render();
  }
  function saveAdminSettings(){
    var d = STATE.adminSettingsDraft; if(!d) return Promise.resolve();
    var isSelf = STATE.session && STATE.session.user && d.id===STATE.session.user.id;
    var list = d.full ? null : ADMIN_MODULES.filter(function(m){ return d.modules[m.key]; }).map(function(m){ return m.key; });
    if(list && !list.length){ showToast('Tick at least one module, or choose Full access.', 'error'); return Promise.resolve(); }
    if(list && isSelf && list.indexOf('access')===-1){ showToast('You can\'t remove your own User Access.', 'error'); return Promise.resolve(); }
    var payload = {admin_modules:list, notify_pending_digest:!!d.digest, notify_payout_reminder:!!d.reminder};
    return supabase.from('profiles').update(payload).eq('id', d.id).then(function(res){
      if(res.error){ showToast('Could not save: '+res.error.message, 'error'); return; }
      STATE.adminSettingsDraft = null;
      showToast('Admin access updated.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  function renderAdminAccess(){
    var today = todayStr();
    var rows = STATE.profiles.map(function(p){
      // Same Terminated/Active/Inactive logic as Employee Directory's Status
      // column (renderAdminStaff), kept in sync here so this screen never
      // disagrees with that one about whether someone can actually log in -
      // a Date of Termination set over on Employee Directory already blocks
      // login on its own (see loadProfileAndData), whether or not anyone
      // has separately clicked Deactivate for them here.
      var isTerminated = p.date_of_termination && p.date_of_termination<=today;
      var statusLabel = isTerminated ? 'Terminated' : (p.active ? 'Active' : 'Inactive');
      var statusClass = (isTerminated || !p.active) ? 'status-rejected' : 'status-approved';
      return '<tr><td>'+escapeHtml(p.name)+'</td><td>'+escapeHtml(p.email)+'</td>'+
        '<td><select data-action="change-role" data-id="'+p.id+'"><option value="user" '+(p.role==='user'?'selected':'')+'>User</option><option value="admin" '+(p.role==='admin'?'selected':'')+'>Admin</option></select></td>'+
        adminAccessCell(p)+
        '<td>'+fmtDate((p.created_at||'').slice(0,10))+'</td>'+
        '<td>'+(!p.active && p.deactivated_at ? fmtDate((p.deactivated_at||'').slice(0,10)) : '-')+'</td>'+
        '<td><span class="status-pill '+statusClass+'">'+statusLabel+'</span></td>'+
        '<td><button class="btn btn-sm btn-ghost" data-action="toggle-active" data-id="'+p.id+'">'+(p.active?'Deactivate':'Activate')+'</button></td>'+
      '</tr>'+
      ((STATE.adminSettingsDraft && STATE.adminSettingsDraft.id===p.id) ? '<tr><td colspan="8">'+renderAdminSettingsPanel(p)+'</td></tr>' : '');
    }).join('');
    return '<div class="card"><div class="card-title">User Access Rights</div><div class="table-wrap"><table class="data-table">'+
      '<thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Admin Access</th><th>Date Added</th><th>Date of Deactivation</th><th>Status</th><th>Actions</th></tr></thead>'+
      '<tbody>'+rows+'</tbody></table></div>'+
      '<div class="field-hint">For administrators, <strong>Manage</strong> chooses which modules they can use and which email alerts they receive. Newly promoted administrators start without User Access and Reimbursement until you tick them.</div>'+
      '<div class="field-hint">Password resets are self-service - employees use "Forgot password?" on the login screen.</div>'+
      '<div class="field-hint">Status shows <strong>Terminated</strong> once an employee\'s Date of Termination (set on Employee Directory) has passed, even if nobody has separately clicked Deactivate for them here - their login is already blocked either way, so there\'s no need to do both.</div>'+
    '</div>';
  }

  function sortArrow(col, activeCol, dir){
    if(col!==activeCol) return '';
    return dir==='asc' ? ' &uarr;' : ' &darr;';
  }
  function sortRows(rows, column, direction, getters){
    if(!column || !getters[column]) return rows;
    var getter = getters[column];
    var sorted = rows.slice().sort(function(a,b){ return getter(a)-getter(b); });
    if(direction==='desc') sorted.reverse();
    return sorted;
  }

  // A calculated-vs-final line for a waivable annual-invoice charge. Shows an
  // inline Waive / Custom Amount editor when STATE.editingWaiverLine matches.
  function waiverLineHtml(lineKey, label, calculatedValue, inv){
    var waiver = (STATE.annualWaivers && STATE.annualWaivers[lineKey]) || {status:'normal'};
    var finalValue = lineKey==='headcountAdjustment' ? inv.adjustmentAmount : inv.baseHeadcountCharge;
    var statusNote = waiver.status==='waived' ? ' <span class="tiny" style="color:var(--danger);">Waived off'+(waiver.reason?(' - '+escapeHtml(waiver.reason)):'')+'</span>'
      : waiver.status==='custom' ? ' <span class="tiny" style="color:var(--accent-dark);">Adjusted'+(waiver.reason?(' - '+escapeHtml(waiver.reason)):'')+'</span>' : '';
    var valueHtml = waiver.status==='normal' ? '<strong>'+fmtMoney(calculatedValue)+'</strong>'
      : '<strong><s class="muted">'+fmtMoney(calculatedValue)+'</s> '+fmtMoney(finalValue)+'</strong>'+statusNote;
    var editorOpen = STATE.editingWaiverLine===lineKey;
    var row = '<tr><td><strong>'+label+'</strong></td><td>'+valueHtml+' <button class="link-btn tiny" data-action="toggle-waiver-editor" data-line="'+lineKey+'">'+(editorOpen?'Close':(waiver.status==='normal'?'Waive / Adjust':'Change'))+'</button></td></tr>';
    if(editorOpen){
      row += '<tr><td colspan="2"><div class="table-wrap" style="margin:6px 0 4px;padding:10px;background:var(--bg);border-radius:8px;display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;">'+
        '<label class="mini-field">Status<select id="waiver-status-'+lineKey+'">'+
          '<option value="normal" '+(waiver.status==='normal'?'selected':'')+'>Normal (as calculated)</option>'+
          '<option value="waived" '+(waiver.status==='waived'?'selected':'')+'>Waived off ($0.00)</option>'+
          '<option value="custom" '+(waiver.status==='custom'?'selected':'')+'>Custom amount</option>'+
        '</select></label>'+
        '<label class="mini-field">Custom Amount (SGD)<input type="number" step="0.01" id="waiver-amount-'+lineKey+'" style="width:120px" value="'+(waiver.amount!=null?waiver.amount:'')+'" placeholder="e.g. 50.00"/></label>'+
        '<label class="mini-field" style="min-width:220px;">Reason (required unless Normal)<input type="text" id="waiver-reason-'+lineKey+'" value="'+escapeHtml(waiver.reason||'')+'" placeholder="e.g. first-year onboarding goodwill"/></label>'+
        '<button class="btn btn-sm btn-primary" data-action="apply-waiver" data-line="'+lineKey+'">Apply</button>'+
      '</div></td></tr>';
    }
    return row;
  }

  function renderAdminFinance(){
    var year = getSelectedInvoiceYear();
    var bounds = benefitYearBounds(year);
    var nextBounds = benefitYearBounds(year+1);
    var yearOptions = buildInvoiceYearOptions();
    var issuedAnnual = STATE.annualInvoices.filter(function(a){ return a.year===year && a.status==='issued'; })[0];
    var isIssuedView = !!(issuedAnnual && issuedAnnual.snapshot_json);
    var inv = isIssuedView ? issuedAnnual.snapshot_json : applyAnnualWaivers(computeAnnualInvoice(year));
    var invoiceDate = fmtDateDMY(addDaysToDateStr(bounds.endStr, 2));
    var invoiceNoLabel = isIssuedView ? ('Invoice No: '+escapeHtml(issuedAnnual.invoice_number)+' (issued '+fmtDate(issuedAnnual.issued_at.slice(0,10))+')') : 'Invoice No: assigned on Issue';

    var rateCell = isIssuedView ? '<span class="muted">Rate used: '+fmtMoney(inv.rate)+' / head / year</span>'
      : (STATE.editingInvoiceRate
        ? '<input type="number" min="0" step="0.01" style="width:100px" id="invoice-rate-input" value="'+inv.rate+'"/> <button class="btn btn-sm btn-primary" data-action="save-invoice-rate">Save</button>'
        : '<span class="muted">Rate: '+fmtMoney(inv.rate)+' / head / year</span> <button class="link-btn" data-action="edit-invoice-rate">Edit</button>');

    var empRows = inv.unutilizedByEmployee.map(function(e){
      return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+fmtMoney(e.allocation)+'</td><td>'+fmtMoney(e.approved)+'</td><td>'+fmtMoney(e.unutilized)+'</td><td class="tiny muted">'+(e.invoiceNumber?escapeHtml(e.invoiceNumber):'&mdash;')+'</td></tr>';
    }).join('');

    var actionButtons = isIssuedView
      ? ('<button class="btn btn-ghost btn-sm" data-action="download-annual-invoice" data-id="'+issuedAnnual.id+'">Download PDF</button>'+
         '<button class="btn btn-ghost btn-sm" data-action="start-void-invoice" data-type="annual" data-id="'+issuedAnnual.id+'">Void</button>')
      : ('<button class="btn btn-ghost btn-sm" data-action="preview-annual-invoice">Preview PDF</button>'+
         '<button class="btn btn-sm btn-primary" data-action="issue-annual-invoice">Issue Invoice</button>');

    var voidPanel = (STATE.voidingInvoice && STATE.voidingInvoice.type==='annual' && STATE.voidingInvoice.id===(issuedAnnual&&issuedAnnual.id)) ? renderVoidPanel() : '';
    var precedingVoidedAnnual = isIssuedView ? null : findUnsupersededVoid(STATE.annualInvoices, function(a){ return a.year===year; });

    return ''+
    '<div class="card">'+
      '<div class="card-title-row">'+
        '<div class="card-title">Annual Invoice</div>'+
        '<div class="report-controls" style="margin-bottom:0;">'+
          '<select data-action="set-invoice-year">'+yearOptions.map(function(y){ return '<option value="'+y+'" '+(y===year?'selected':'')+'>'+escapeHtml(benefitYearLabel(y))+'</option>'; }).join('')+'</select>'+
          actionButtons+
        '</div>'+
      '</div>'+
      '<div class="report-summary" style="margin-bottom:16px;">Period: '+fmtDateDMY(bounds.startStr)+' - '+fmtDateDMY(bounds.endStr)+' &middot; Invoice date '+invoiceDate+' &middot; '+invoiceNoLabel+' &middot; '+rateCell+
        (isIssuedView?'':' <span class="tiny muted">&middot; Preview only - nothing is saved until you Issue</span>')+
        (precedingVoidedAnnual ? (' <span class="tiny" style="color:var(--accent-dark);">&middot; Issuing now will supersede voided invoice '+escapeHtml(precedingVoidedAnnual.invoice_number)+'</span>') : '')+
      '</div>'+
      voidPanel+
      '<div class="grid-cards">'+
        '<div class="card stat"><div class="stat-label">Total Headcount Charge</div><div class="stat-value">'+fmtMoney(inv.totalHeadcountCharge)+'</div></div>'+
        '<div class="card stat"><div class="stat-label">Unutilised Benefit</div><div class="stat-value">'+fmtMoney(inv.totalUnutilized)+'</div></div>'+
        '<div class="card stat"><div class="stat-label">Total Credit Note</div><div class="stat-value">'+fmtMoney(inv.creditNoteAmount)+'</div></div>'+
        '<div class="card stat"><div class="stat-label">'+(inv.netAmount>=0?'Net Amount Due':'Net Credit Balance')+'</div><div class="stat-value">'+fmtMoney(Math.abs(inv.netAmount))+'</div></div>'+
        '<div class="card stat highlight"><div class="stat-label">Invoice Payable Amount</div><div class="stat-value">'+fmtMoney(inv.invoicePayableAmount)+'</div></div>'+
      '</div>'+
    '</div>'+
    '<div class="card">'+
      '<div class="card-title">Calculation Detail</div>'+
      '<details open><summary class="link-btn" style="cursor:pointer;">Headcount Adjustment (True-Up for '+benefitYearLabel(year)+')</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table"><tbody>'+
          '<tr><td>Headcount as at '+fmtDateDMY(bounds.startStr)+'</td><td>'+inv.startHeadcount+'</td></tr>'+
          '<tr><td>Headcount as at '+fmtDateDMY(bounds.endStr)+'</td><td>'+inv.endHeadcount+'</td></tr>'+
          '<tr><td>Net Change</td><td>'+inv.headcountDelta+'</td></tr>'+
          '<tr><td>Adjustment Units (Net Change &divide; 2)</td><td>'+inv.adjustmentUnits+'</td></tr>'+
          '<tr><td>Rate per Headcount</td><td>'+fmtMoney(inv.rate)+'</td></tr>'+
          (isIssuedView
            ? '<tr><td><strong>Headcount Adjustment Amount</strong></td><td><strong>'+fmtMoney(inv.adjustmentAmount)+'</strong>'+(inv.adjustmentWaiver&&inv.adjustmentWaiver.status!=='normal'?' <span class="tiny muted">('+inv.adjustmentWaiver.status+(inv.adjustmentWaiver.reason?' - '+escapeHtml(inv.adjustmentWaiver.reason):'')+')</span>':'')+'</td></tr>'
            : waiverLineHtml('headcountAdjustment','Headcount Adjustment Amount', computeAnnualInvoice(year).adjustmentAmount, inv))+
        '</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">Headcount Charge for '+benefitYearLabel(year+1)+' ('+inv.newYearHeadcount+' employees)</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table"><tbody>'+
          '<tr><td>Headcount as at '+fmtDateDMY(nextBounds.startStr)+'</td><td>'+inv.newYearHeadcount+'</td></tr>'+
          '<tr><td>Rate per Headcount</td><td>'+fmtMoney(inv.rate)+'</td></tr>'+
          (isIssuedView
            ? '<tr><td><strong>Base Headcount Charge</strong></td><td><strong>'+fmtMoney(inv.baseHeadcountCharge)+'</strong>'+(inv.baseWaiver&&inv.baseWaiver.status!=='normal'?' <span class="tiny muted">('+inv.baseWaiver.status+(inv.baseWaiver.reason?' - '+escapeHtml(inv.baseWaiver.reason):'')+')</span>':'')+'</td></tr>'
            : waiverLineHtml('baseHeadcountCharge','Base Headcount Charge', computeAnnualInvoice(year).baseHeadcountCharge, inv))+
          '<tr><td><strong>Total Headcount Charge (Base + Adjustment)</strong></td><td><strong>'+fmtMoney(inv.totalHeadcountCharge)+'</strong></td></tr>'+
        '</tbody></table></div>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table">'+
        '<thead><tr><th>Employee</th><th>Annual Allocation</th></tr></thead>'+
        '<tbody>'+(inv.newYearHeadcountList.length ? inv.newYearHeadcountList.map(function(e){ return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+fmtMoney(e.allocation)+'</td></tr>'; }).join('') : '<tr><td colspan="2" class="muted">No employees on record as at '+fmtDateDMY(nextBounds.startStr)+'.</td></tr>')+'</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">Headcount as at '+fmtDateDMY(bounds.startStr)+' ('+inv.startHeadcountList.length+' employees)</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table">'+
        '<thead><tr><th>Employee</th><th>Annual Allocation</th></tr></thead>'+
        '<tbody>'+(inv.startHeadcountList.length ? inv.startHeadcountList.map(function(e){ return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+fmtMoney(e.allocation)+'</td></tr>'; }).join('') : '<tr><td colspan="2" class="muted">No employees on record as at '+fmtDateDMY(bounds.startStr)+'.</td></tr>')+'</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">New Joiners in '+benefitYearLabel(year)+' ('+inv.newJoinersList.length+' employees)</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table">'+
        '<thead><tr><th>Employee</th><th>Effective Date</th><th>Months Billed</th><th>Entitlement</th><th>Invoice #</th></tr></thead>'+
        '<tbody>'+(inv.newJoinersList.length ? inv.newJoinersList.map(function(e){ return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+fmtDate(e.date)+'</td><td>'+e.months+' of 12</td><td>'+fmtMoney(e.allocation)+'</td><td class="tiny muted">'+(e.invoiceNumber?escapeHtml(e.invoiceNumber):'&mdash; (estimated, not yet invoiced)')+'</td></tr>'; }).join('') : '<tr><td colspan="5" class="muted">No new joiners recorded in '+year+'.</td></tr>')+'</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">Terminations in '+year+' ('+inv.terminationsList.length+' employees)</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table">'+
        '<thead><tr><th>Employee</th><th>Termination Date</th><th>Months Actually Employed</th><th>Annual Allocation (billed in full)</th></tr></thead>'+
        '<tbody>'+(inv.terminationsList.length ? inv.terminationsList.map(function(e){ return '<tr><td>'+escapeHtml(e.name)+'</td><td>'+fmtDate(e.date)+'</td><td>'+e.months+' of 12</td><td>'+fmtMoney(e.allocation)+'</td></tr>'; }).join('') : '<tr><td colspan="4" class="muted">No terminations recorded in '+year+'.</td></tr>')+'</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">Unutilised Benefit</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table"><tbody>'+
          '<tr><td>Total Entitlement Pool for '+year+'</td><td>'+fmtMoney(inv.totalEntitlementPool)+'</td></tr>'+
          '<tr><td>Total Approved Claims for '+year+'</td><td>'+fmtMoney(inv.totalApprovedForYear)+'</td></tr>'+
          '<tr><td>Total Unutilised Amount</td><td>'+fmtMoney(inv.totalUnutilized)+'</td></tr>'+
        '</tbody></table></div>'+
      '</details>'+
      '<details style="margin-top:12px;"><summary class="link-btn" style="cursor:pointer;">By Employee</summary>'+
        '<div class="table-wrap" style="margin-top:10px;"><table class="data-table">'+
        '<thead><tr><th>Employee</th><th>Entitlement</th><th>Approved Claims</th><th>Unutilised</th><th>Invoice #</th></tr></thead>'+
        '<tbody>'+empRows+'</tbody></table></div>'+
      '</details>'+
      '<div class="field-hint" style="margin-top:14px;">Credit note balance can be applied to offset next year\'s benefit charges. "Invoice #" traces an employee\'s entitlement figure back to the New Hire / Promotion invoice that actually billed it - a dash means no such invoice exists on record and the full or estimated allocation was used instead.</div>'+
    '</div>';
  }

  function renderVoidPanel(){
    return '<div class="info-banner banner-warning" style="margin-bottom:14px;">'+
      '<div style="font-weight:700;margin-bottom:8px;">Void this invoice</div>'+
      '<label class="mini-field" style="margin-bottom:8px;">Reason (required)<input type="text" id="void-reason-input" value="'+escapeHtml(STATE.voidReasonDraft||'')+'" placeholder="e.g. client disputed the headcount figure" style="width:100%;max-width:420px;"/></label>'+
      '<div><button class="btn btn-sm btn-primary" data-action="confirm-void-invoice">Confirm Void</button> '+
      '<button class="btn btn-sm btn-ghost" data-action="cancel-void-invoice">Cancel</button></div>'+
    '</div>';
  }

  function entitlementItemRowHtml(item){
    var sel = getEntitlementSelection(item.key, item.defaultProrate);
    var finalAmount = finalAmountForSelection(item, sel);
    var calculatedAmount = sel.prorate ? item.proratedAmount : item.fullAmount;
    var typeLabel = item.type==='promotion' ? 'Promotion / Adjustment' : 'New Hire';
    var waiveOpen = STATE.editingWaiverLine===item.key;
    var amountHtml = sel.waiveStatus==='normal' ? fmtMoney(calculatedAmount)
      : '<s class="muted">'+fmtMoney(calculatedAmount)+'</s> '+fmtMoney(finalAmount)+(sel.waiveStatus==='waived'?' <span class="tiny" style="color:var(--danger);">Waived off</span>':' <span class="tiny" style="color:var(--accent-dark);">Adjusted</span>');
    var row = '<tr>'+
      '<td><input type="checkbox" data-action="toggle-entitlement-check" data-key="'+item.key+'" '+(sel.checked?'checked':'')+'/></td>'+
      '<td>'+escapeHtml(item.employeeName)+(item.employeeEmail?'<div class="tiny muted">'+escapeHtml(item.employeeEmail)+'</div>':'')+'</td>'+
      '<td>'+typeLabel+(item.type==='promotion'?'<div class="tiny muted">'+fmtMoney(item.oldAllocation)+' &rarr; '+fmtMoney(item.newAllocation)+'</div>':'')+'</td>'+
      '<td>'+fmtDate(item.effectiveDate)+'</td>'+
      '<td><label class="tiny"><input type="checkbox" data-action="toggle-entitlement-prorate" data-key="'+item.key+'" '+(sel.prorate?'checked':'')+'/> Prorate ('+item.months+' of 12)</label></td>'+
      '<td>'+amountHtml+' <button class="link-btn tiny" data-action="toggle-entitlement-waiver" data-key="'+item.key+'">'+(waiveOpen?'Close':(sel.waiveStatus==='normal'?'Waive/Adjust':'Change'))+'</button></td>'+
    '</tr>';
    if(waiveOpen){
      row += '<tr><td colspan="6"><div style="margin:6px 0 4px;padding:10px;background:var(--bg);border-radius:8px;display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;">'+
        '<label class="mini-field">Status<select id="ent-waiver-status-'+item.key+'">'+
          '<option value="normal" '+(sel.waiveStatus==='normal'?'selected':'')+'>Normal (as calculated)</option>'+
          '<option value="waived" '+(sel.waiveStatus==='waived'?'selected':'')+'>Waived off ($0.00)</option>'+
          '<option value="custom" '+(sel.waiveStatus==='custom'?'selected':'')+'>Custom amount</option>'+
        '</select></label>'+
        '<label class="mini-field">Custom Amount (SGD)<input type="number" step="0.01" id="ent-waiver-amount-'+item.key+'" style="width:120px" value="'+(sel.overrideAmount!=null?sel.overrideAmount:'')+'"/></label>'+
        '<label class="mini-field" style="min-width:220px;">Reason (required unless Normal)<input type="text" id="ent-waiver-reason-'+item.key+'" value="'+escapeHtml(sel.waiveReason||'')+'"/></label>'+
        '<button class="btn btn-sm btn-primary" data-action="apply-entitlement-waiver" data-key="'+item.key+'">Apply</button>'+
      '</div></td></tr>';
    }
    return row;
  }

  // Money Holding / Total Planned Entitlement transparency panel shown at
  // the top of New Hire Invoicing, so the 80% figure driving the badge is
  // never a black box - the admin sees the exact numbers it came from.
  function renderEntitlementCushionPanel(){
    var c = entitlementCushionStatus();
    var pctLabel = c.planned>0 ? Math.round(c.utilisation*100)+'%' : '&mdash;';
    var statusLine = c.planned<=0
      ? 'No active employees yet - nothing to fund.'
      : c.belowThreshold
        ? ('80% or more of the total entitlement has been utilised - '+c.reminderCount+' item'+(c.reminderCount===1?'':'s')+' below (new hires and/or promotions) should be batched into an invoice to top up the float.')
        : 'Utilisation is under 80% - any new hires or promotions below can wait; no invoicing required yet.';
    var statusColor = (c.planned>0 && c.belowThreshold) ? 'var(--danger)' : 'var(--success)';
    var unpaidCount = unpaidEntitlementInvoices().length;
    return '<div class="report-summary" style="margin-bottom:8px;">'+
        'Money Holding: <strong>'+fmtMoney(c.holding)+'</strong> &middot; '+
        'Total Planned Entitlement: <strong>'+fmtMoney(c.planned)+'</strong> &middot; '+
        'Utilisation: <strong>'+pctLabel+'</strong>'+
      '</div>'+
      '<div class="field-hint" style="margin-bottom:14px; color:'+statusColor+';">'+statusLine+'</div>'+
      (unpaidCount ? ('<div class="field-hint" style="margin-bottom:14px; color:var(--warning);">'+unpaidCount+' issued invoice'+(unpaidCount===1?'':'s')+' awaiting payment confirmation - Money Holding above won\'t include '+(unpaidCount===1?'it':'them')+' until marked Paid on Invoice History.</div>') : '');
  }

  function renderAdminNewHireInvoicing(){
    var allPending = pendingEntitlementItems();
    var from = STATE.entitlementDateFrom, to = STATE.entitlementDateTo;
    var pending = allPending.filter(function(item){
      if(from && item.effectiveDate<from) return false;
      if(to && item.effectiveDate>to) return false;
      return true;
    });
    var preview = computeEntitlementInvoicePreview();
    var isInitial = preview.invoiceType==='initial';
    var rows = pending.map(entitlementItemRowHtml).join('');
    var precedingVoidedEnt = findUnsupersededVoid(STATE.entitlementInvoices, function(){ return true; });

    return ''+
    '<div class="card">'+
      '<div class="card-title">New Hire Invoicing</div>'+
      renderEntitlementCushionPanel()+
      '<div class="field-hint" style="margin-bottom:14px;">Every employee who hasn\'t yet been entitlement-invoiced, and every allocation change (promotion) awaiting invoicing - across any date range, not just one month. Tick whoever you\'re billing now; unticked rows just stay here for next time.'+
        (isInitial ? ' <strong>This will be this client\'s Initial Invoice</strong> - it also adds a one-time per-pax headcount establishment charge for every employee included.' : '')+
        ' The <strong>Prorate</strong> checkbox below starts from that employee\'s own setting (Employee Management &rarr; Prorate column) but only affects <em>this invoice</em> - toggling it here is a one-time override for this billing run and never changes what the employee sees in their own wallet.'+
      '</div>'+
      '<div class="report-controls" style="margin-bottom:14px;">'+
        '<label class="mini-field">From<input type="date" data-action="set-entitlement-date-from" value="'+(from||'')+'"/></label>'+
        '<label class="mini-field">To<input type="date" data-action="set-entitlement-date-to" value="'+(to||'')+'"/></label>'+
        (from||to ? '<button class="link-btn" data-action="clear-entitlement-date-filter">Clear filter</button>' : '')+
      '</div>'+
      (pending.length ? (
      '<div class="table-wrap"><table class="data-table">'+
        '<thead><tr><th></th><th>Employee</th><th>Type</th><th>Effective Date</th><th>Prorate</th><th>Amount</th></tr></thead>'+
        '<tbody>'+rows+'</tbody>'+
      '</table></div>')
      : '<div class="empty-state">Nothing pending - every employee and allocation change has already been invoiced.</div>')+
      (preview.lines.length ? (
      '<div class="report-summary" style="margin-top:16px;">'+
        (isInitial ? ('Per-Pax Establishment Charge: '+preview.headcountForPax+' &times; '+fmtMoney(preview.rate)+' = '+fmtMoney(preview.perPaxTotal)+' &middot; ') : '')+
        'Entitlement Total: '+fmtMoney(preview.entitlementTotal)+' &middot; <strong>Total Amount: '+fmtMoney(preview.totalAmount)+'</strong>'+
        (precedingVoidedEnt ? (' <span class="tiny" style="color:var(--accent-dark);">&middot; Issuing now will supersede voided invoice '+escapeHtml(precedingVoidedEnt.invoice_number)+'</span>') : '')+
      '</div>'+
      '<div style="margin-top:12px;">'+
        '<button class="btn btn-ghost btn-sm" data-action="preview-entitlement-invoice">Preview PDF</button> '+
        '<button class="btn btn-sm btn-primary" data-action="issue-entitlement-invoice">Issue Invoice</button>'+
      '</div>'+
      '<div class="tiny muted" style="margin-top:6px;">Preview is a live calculation only - nothing is saved or numbered until you Issue.</div>')
      : '')+
    '</div>';
  }

  /* ---------------------------------------------------------------------
     REIMBURSEMENT (Finance > Reimbursement tab)
     -----------------------------------------------------------------------
     Claims are paid in monthly batches. The database stamps every claim with
     a payout_date when it is submitted (claim_reimbursement_date() in
     migration 017: submitted on/before the 28th -> the 7th of next month,
     otherwise the 7th of the month after; a weekend or Singapore public
     holiday moves it to the next working day). This tab just groups approved
     claims by that stamped date, so the rule lives in ONE place (SQL).
     REIMBURSEMENT_CUTOFF_DAY below only labels each batch's submission
     window ("29 Sep - 28 Oct"); keep it equal to the 28 in that function.
  --------------------------------------------------------------------- */
  var REIMBURSEMENT_CUTOFF_DAY = 28;
  var WEEKDAY_SHORT = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  function sgDateStrOf(iso){
    // YYYY-MM-DD of an instant as seen in Singapore (en-CA formats as ISO date)
    return new Date(iso).toLocaleDateString('en-CA', {timeZone:'Asia/Singapore'});
  }
  function sgTodayStr(){ return sgDateStrOf(new Date().toISOString()); }
  function fmtDateWithWeekday(dateStr){
    var p = dateStr.split('-').map(Number);
    return WEEKDAY_SHORT[new Date(Date.UTC(p[0], p[1]-1, p[2])).getUTCDay()]+' '+fmtDateDMY(dateStr);
  }
  // "29 Sep - 28 Oct" for a batch paid in the month of payoutStr: claims
  // submitted after the cut-off two months back, up to the cut-off last month.
  function reimbursementWindowLabel(payoutStr){
    var p = payoutStr.split('-').map(Number);
    var endD = new Date(Date.UTC(p[0], p[1]-1-1, REIMBURSEMENT_CUTOFF_DAY));
    var startD = new Date(Date.UTC(p[0], p[1]-1-2, REIMBURSEMENT_CUTOFF_DAY));
    var endStr = endD.toISOString().slice(0,10);
    var startStr = addDaysToDateStr(startD.toISOString().slice(0,10), 1);
    return fmtDateDMY(startStr)+' - '+fmtDateDMY(endStr);
  }
  function approvedClaimsByPayoutDate(){
    var byDate = {};
    (STATE.claims||[]).forEach(function(c){
      if(c.status!=='approved' || !c.payout_date) return;
      (byDate[c.payout_date] = byDate[c.payout_date] || []).push(c);
    });
    return byDate;
  }
  // Approved claims whose payout date has arrived (or passed) and that haven't
  // been marked reimbursed - the Reimbursement sub-tab badge.
  function reimbursementDueClaims(){
    var today = sgTodayStr();
    return (STATE.claims||[]).filter(function(c){
      return c.status==='approved' && c.payout_date && !c.reimbursed_at && c.payout_date <= today;
    });
  }
  function reimbursementSelectedCycle(byDate){
    var dates = Object.keys(byDate).sort();
    if(STATE.reimbursementCycle && byDate[STATE.reimbursementCycle]) return STATE.reimbursementCycle;
    for(var i=0;i<dates.length;i++){
      if(byDate[dates[i]].some(function(c){ return !c.reimbursed_at; })) return dates[i];
    }
    return dates.length ? dates[dates.length-1] : null;
  }
  // One row per claimant still to be paid in this batch, then one row per
  // claimant already paid (a claim approved late, after the batch was paid,
  // becomes its own "to pay" row next to that person's "reimbursed" row).
  function reimbursementRowsFor(claims){
    function group(list){
      var map = {}, order = [];
      list.forEach(function(c){
        if(!map[c.employee_id]){ map[c.employee_id] = {empId:c.employee_id, claims:[], total:0}; order.push(c.employee_id); }
        map[c.employee_id].claims.push(c);
        map[c.employee_id].total += sgdAmountOf(c);
      });
      return order.map(function(id){ return map[id]; }).sort(function(a,b){
        var pa = profileById(a.empId), pb = profileById(b.empId);
        return ((pa&&pa.name)||'').localeCompare((pb&&pb.name)||'');
      });
    }
    var todo = group(claims.filter(function(c){ return !c.reimbursed_at; }));
    var done = group(claims.filter(function(c){ return !!c.reimbursed_at; }));
    done.forEach(function(r){
      r.reimbursedOn = r.claims.map(function(c){ return c.reimbursed_at; }).sort().slice(-1)[0];
    });
    return {todo:todo, done:done};
  }
  function reimbursementSelection(todoRows){
    var picked = todoRows.filter(function(r){ return STATE.reimbursementChecked[r.empId]; });
    return {
      rows: picked,
      claimIds: picked.reduce(function(a,r){ return a.concat(r.claims.map(function(c){ return c.id; })); }, []),
      total: picked.reduce(function(s,r){ return s+r.total; }, 0)
    };
  }

  function renderAdminReimbursement(){
    var intro = '<div class="field-hint" style="margin-bottom:14px;">Approved claims grouped by reimbursement date. Claims submitted on or before the '+REIMBURSEMENT_CUTOFF_DAY+'th are paid on the 7th of the next month (the next working day if the 7th is a weekend or public holiday); claims submitted after the '+REIMBURSEMENT_CUTOFF_DAY+'th are paid a month later. Tick the claimants you have paid and press Update - each person is emailed to confirm their reimbursement.</div>';
    var anyClaims = (STATE.claims||[]).length>0;
    if(anyClaims && !(STATE.claims||[]).some(function(c){ return Object.prototype.hasOwnProperty.call(c,'payout_date'); })){
      return '<div class="card"><div class="card-title">Reimbursement</div><div class="empty-state">This tab needs database migration 017 (017_reimbursement_cycle.sql) to be run in the Supabase SQL Editor first.</div></div>';
    }
    var byDate = approvedClaimsByPayoutDate();
    var dates = Object.keys(byDate).sort();
    if(!dates.length){
      return '<div class="card"><div class="card-title">Reimbursement</div>'+intro+'<div class="empty-state">No approved claims yet.</div></div>';
    }
    var cycle = reimbursementSelectedCycle(byDate);
    var cycleClaims = byDate[cycle];
    var rowsInfo = reimbursementRowsFor(cycleClaims);
    var sel = reimbursementSelection(rowsInfo.todo);
    var pendingInBatch = (STATE.claims||[]).filter(function(c){ return c.status==='pending' && c.payout_date===cycle; }).length;
    var today = sgTodayStr();

    var cycleOptions = dates.map(function(d){
      var outstanding = byDate[d].filter(function(c){ return !c.reimbursed_at; }).length;
      var tag = outstanding ? (outstanding+' to pay') : 'all paid';
      return '<option value="'+d+'" '+(d===cycle?'selected':'')+'>'+escapeHtml(fmtDateWithWeekday(d)+' - claims submitted '+reimbursementWindowLabel(d)+' ('+tag+')')+'</option>';
    }).join('');

    function mobileCell(empId){
      var pr = profileById(empId);
      return (pr && pr.paynow_mobile) ? escapeHtml(pr.paynow_mobile) : '<span class="muted">&mdash;</span>';
    }
    function nameCell(empId){
      var pr = profileById(empId);
      return escapeHtml(pr ? pr.name : 'Unknown employee');
    }
    function shortDM(str){ var q = str.split('-').map(Number); return q[2]+' '+REPORT_MONTH_NAMES[q[1]-1].slice(0,3); }
    function submittedRange(list){
      var ds = list.map(function(c){ return sgDateStrOf(c.submitted_at); }).sort();
      return ds[0]===ds[ds.length-1] ? shortDM(ds[0]) : (shortDM(ds[0])+' - '+shortDM(ds[ds.length-1]));
    }
    // One row per claimant (todo = still to pay, done = already reimbursed),
    // each with an open/close arrow that lists that person's claims with
    // their submission and approval dates.
    function claimantRows(list, state){
      return list.map(function(r){
        var key = r.empId+'|'+state;
        var open = !!STATE.reimbursementExpanded[key];
        var sorted = r.claims.slice().sort(function(x,y){ return x.submitted_at.localeCompare(y.submitted_at); });
        var lastCell = state==='todo'
          ? '<label style="cursor:pointer;"><input type="checkbox" data-action="toggle-reimb-emp" data-emp-id="'+r.empId+'" '+(STATE.reimbursementChecked[r.empId]?'checked':'')+'/> Reimbursed</label>'
          : '<label class="tiny muted"><input type="checkbox" checked disabled/> Reimbursed '+fmtDateDMY(sgDateStrOf(r.reimbursedOn))+'</label>';
        var main = '<tr class="'+(state==='done'?'reimb-done-row':'')+'">'+
          '<td><button class="link-btn" style="text-decoration:none;" data-action="toggle-reimb-detail" data-key="'+key+'" title="Show this person\'s claims">'+(open?'&#9660;':'&#9654;')+'</button> '+nameCell(r.empId)+'</td>'+
          '<td>'+mobileCell(r.empId)+'</td>'+
          '<td>'+r.claims.length+'</td>'+
          '<td>'+submittedRange(sorted)+'</td>'+
          '<td>'+fmtMoney(r.total)+'</td>'+
          '<td>'+lastCell+'</td>'+
        '</tr>';
        var detail = '';
        if(open){
          detail = '<tr class="claim-detail-row"><td colspan="6"><div class="claim-detail-wrap"><table class="claim-detail-table">'+
            '<thead><tr><th>Category</th><th>Vendor</th><th>Submitted</th><th>Approved</th><th>Amount</th></tr></thead><tbody>'+
            sorted.map(function(c){
              return '<tr><td>'+escapeHtml(c.category)+'</td><td>'+escapeHtml(c.vendor||'-')+'</td>'+
                '<td>'+fmtDateDMY(sgDateStrOf(c.submitted_at))+'</td>'+
                '<td>'+(c.decided_at ? fmtDateDMY(sgDateStrOf(c.decided_at)) : '-')+'</td>'+
                '<td>'+fmtMoney(sgdAmountOf(c))+((c.currency && c.currency!=='SGD') ? ' <span class="tiny muted">('+escapeHtml(fmtCurrencyAmount(c.currency, c.amount))+')</span>' : '')+'</td></tr>';
            }).join('')+
            '<tr class="total-row"><td colspan="4">Total - '+r.claims.length+' claim'+(r.claims.length===1?'':'s')+'</td><td>'+fmtMoney(r.total)+'</td></tr>'+
          '</tbody></table></div></td></tr>';
        }
        return main+detail;
      }).join('');
    }
    var todoHtml = claimantRows(rowsInfo.todo, 'todo');
    var doneHtml = claimantRows(rowsInfo.done, 'done');

    var todoTotal = rowsInfo.todo.reduce(function(s,r){ return s+r.total; }, 0);
    var todoClaims = rowsInfo.todo.reduce(function(s,r){ return s+r.claims.length; }, 0);
    var allTicked = rowsInfo.todo.length>0 && sel.rows.length===rowsInfo.todo.length;

    var dueNote = '';
    if(rowsInfo.todo.length){
      dueNote = cycle > today
        ? '<span class="tiny muted">Reimbursement date is '+fmtDateWithWeekday(cycle)+' - not due yet.</span>'
        : '<span class="tiny" style="color:var(--warning);">Reimbursement date '+fmtDateWithWeekday(cycle)+' has arrived - '+rowsInfo.todo.length+' claimant'+(rowsInfo.todo.length===1?'':'s')+' still to pay.</span>';
    }

    var actionBar = '';
    if(rowsInfo.todo.length){
      if(STATE.reimbursementConfirming && sel.rows.length){
        actionBar = '<div class="field-hint" style="margin-top:14px; color:var(--warning);">Mark <strong>'+sel.rows.length+' claimant'+(sel.rows.length===1?'':'s')+'</strong> ('+fmtMoney(sel.total)+' in total) as reimbursed and email '+(sel.rows.length===1?'them':'each of them')+' now? The email cannot be recalled and these rows cannot be un-ticked afterwards. '+
          '<button class="btn btn-sm btn-primary" data-action="reimb-update-confirm" '+(STATE.reimbursementBusy?'disabled':'')+'>'+(STATE.reimbursementBusy?'Updating...':'Yes, update & email')+'</button> '+
          '<button class="btn btn-sm" data-action="reimb-update-cancel" '+(STATE.reimbursementBusy?'disabled':'')+'>Cancel</button></div>';
      } else {
        actionBar = '<div style="margin-top:14px; display:flex; gap:12px; align-items:center; flex-wrap:wrap;">'+
          '<button class="btn btn-primary" data-action="reimb-update-start" '+(sel.rows.length?'':'disabled')+'>Update</button>'+
          '<span class="tiny muted">'+(sel.rows.length ? (sel.rows.length+' selected - '+fmtMoney(sel.total)) : 'Tick the claimants you have reimbursed, then press Update.')+'</span>'+
        '</div>';
      }
    }

    return '<div class="card">'+
      '<div class="card-title">Reimbursement</div>'+intro+
      '<div style="display:flex; gap:14px; align-items:center; flex-wrap:wrap; margin-bottom:10px;">'+
        '<label class="tiny muted">Reimbursement date <select data-action="set-reimbursement-cycle" style="max-width:100%;">'+cycleOptions+'</select></label>'+
        dueNote+
      '</div>'+
      (pendingInBatch ? '<div class="field-hint" style="margin-bottom:10px;">'+pendingInBatch+' claim'+(pendingInBatch===1?'':'s')+' submitted for this batch '+(pendingInBatch===1?'is':'are')+' still awaiting approval and will appear here once approved.</div>' : '')+
      '<div class="table-wrap"><table class="data-table">'+
        '<thead><tr><th>Claimant</th><th>Mobile Number</th><th>No. of Claims</th><th>Submitted</th><th>Claim Amount</th>'+
          '<th>Reimbursed '+(rowsInfo.todo.length ? '<label class="tiny muted" style="text-transform:none; letter-spacing:0; font-weight:400; cursor:pointer;"><input type="checkbox" data-action="reimb-select-all" '+(allTicked?'checked':'')+'/> all</label>' : '')+'</th></tr></thead>'+
        '<tbody>'+todoHtml+doneHtml+'</tbody>'+
        (rowsInfo.todo.length ? '<tfoot><tr><td colspan="2"><strong>To reimburse</strong></td><td><strong>'+todoClaims+'</strong></td><td></td><td><strong>'+fmtMoney(todoTotal)+'</strong></td><td></td></tr></tfoot>' : '')+
      '</table></div>'+
      (rowsInfo.todo.length ? '' : '<div class="field-hint" style="margin-top:12px;">Everyone in this batch has been reimbursed.</div>')+
      actionBar+
    '</div>';
  }

  // Marks the ticked claimants' approved claims in the shown batch as
  // reimbursed. The database function does the marking AND sends each
  // claimant one email (plus an in-app notification), so this can't drift
  // out of step with what the person is told.
  function runReimbursementUpdate(){
    var byDate = approvedClaimsByPayoutDate();
    var cycle = reimbursementSelectedCycle(byDate);
    if(!cycle) return Promise.resolve();
    var sel = reimbursementSelection(reimbursementRowsFor(byDate[cycle]).todo);
    if(!sel.claimIds.length){ STATE.reimbursementConfirming = false; render(); return Promise.resolve(); }
    STATE.reimbursementBusy = true; STATE.reimbursementCycle = cycle; render();
    return supabase.rpc('mark_claims_reimbursed', {p_claim_ids: sel.claimIds}).then(function(res){
      if(res.error){
        STATE.reimbursementBusy = false; STATE.reimbursementConfirming = false;
        var m = res.error.message || String(res.error);
        showToast(/mark_claims_reimbursed/.test(m) && /not exist|find the function|schema cache/i.test(m) ? 'Run database migration 017 in Supabase first.' : ('Could not update: '+m), 'error');
        render();
        return;
      }
      var out = res.data || {};
      STATE.reimbursementChecked = {}; STATE.reimbursementConfirming = false; STATE.reimbursementBusy = false;
      showToast((out.people_notified||0)+' claimant'+((out.people_notified||0)===1?'':'s')+' marked reimbursed and notified.', 'success');
      return loadAppData().then(function(){ render(); });
    });
  }

  function renderAdminInvoiceHistory(){
    var entRows = STATE.entitlementInvoices.slice().sort(function(a,b){ return (b.issued_at||'').localeCompare(a.issued_at||''); }).map(function(inv){
      var itemCount = STATE.entitlementInvoiceItems.filter(function(i){ return i.invoice_id===inv.id; }).length;
      var typeLabel = inv.invoice_type==='initial' ? 'Initial Roster Invoice' : 'New Hire / Promotion Invoice';
      var statusHtml = inv.status==='voided' ? '<span class="tiny" style="color:var(--danger);">Voided'+(inv.voided_reason?(' - '+escapeHtml(inv.voided_reason)):'')+'</span>' : '<span class="tiny" style="color:var(--success);">Issued</span>';
      var voidBtn = inv.status==='issued' ? '<button class="link-btn tiny" data-action="start-void-invoice" data-type="entitlement" data-id="'+inv.id+'">Void</button>' : '';
      var supersedesRow = inv.supersedes_invoice_id ? STATE.entitlementInvoices.filter(function(i){ return i.id===inv.supersedes_invoice_id; })[0] : null;
      var numberCell = escapeHtml(inv.invoice_number)+(supersedesRow ? '<div class="tiny muted">supersedes '+escapeHtml(supersedesRow.invoice_number)+'</div>' : '');
      // Only entitlement invoices carry a Paid flag at all (see
      // moneyHoldingBalance's comment) - a voided one shows a dash since
      // there's nothing left to collect on it either way.
      var paidByProfile = inv.paid_by ? profileById(inv.paid_by) : null;
      var paidDetail = inv.paid
        ? ('Paid'+(inv.paid_at?(' '+fmtDate(inv.paid_at.slice(0,10))):'')+(paidByProfile?(' by '+escapeHtml(paidByProfile.name)):''))
        : '<span style="color:var(--danger); font-weight:600;">Awaiting payment</span>';
      var paymentCell = inv.status!=='issued' ? '<span class="tiny muted">&mdash;</span>' :
        '<label class="tiny" style="white-space:nowrap; cursor:pointer;"><input type="checkbox" data-action="toggle-invoice-paid" data-id="'+inv.id+'" '+(inv.paid?'checked':'')+'/> '+paidDetail+'</label>';
      return '<tr><td>'+numberCell+'</td><td>'+typeLabel+'</td><td>'+fmtDate((inv.issued_at||'').slice(0,10))+'</td><td>'+itemCount+'</td><td>'+fmtMoney(inv.total_amount)+'</td><td>'+statusHtml+'</td><td>'+paymentCell+'</td>'+
        '<td><button class="link-btn tiny" data-action="download-entitlement-invoice" data-id="'+inv.id+'">Download</button> '+voidBtn+'</td></tr>'+
        ((STATE.voidingInvoice && STATE.voidingInvoice.type==='entitlement' && STATE.voidingInvoice.id===inv.id) ? '<tr><td colspan="8">'+renderVoidPanel()+'</td></tr>' : '');
    }).join('');
    var annRows = STATE.annualInvoices.slice().sort(function(a,b){ return (b.issued_at||'').localeCompare(a.issued_at||''); }).map(function(inv){
      var statusHtml = inv.status==='voided' ? '<span class="tiny" style="color:var(--danger);">Voided'+(inv.voided_reason?(' - '+escapeHtml(inv.voided_reason)):'')+'</span>' : '<span class="tiny" style="color:var(--success);">Issued</span>';
      var voidBtn = inv.status==='issued' ? '<button class="link-btn tiny" data-action="start-void-invoice" data-type="annual" data-id="'+inv.id+'">Void</button>' : '';
      var annSupersedesRow = inv.supersedes_invoice_id ? STATE.annualInvoices.filter(function(a){ return a.id===inv.supersedes_invoice_id; })[0] : null;
      var annNumberCell = escapeHtml(inv.invoice_number)+(annSupersedesRow ? '<div class="tiny muted">supersedes '+escapeHtml(annSupersedesRow.invoice_number)+'</div>' : '');
      // Headcount charges settle through next year's True-Up regardless of
      // when they're paid, so the Annual Invoice never shows a Paid toggle.
      return '<tr><td>'+annNumberCell+'</td><td>Annual Invoice ('+inv.year+')</td><td>'+fmtDate((inv.issued_at||'').slice(0,10))+'</td><td>&mdash;</td><td>'+fmtMoney(inv.invoice_payable_amount)+'</td><td>'+statusHtml+'</td><td><span class="tiny muted">N/A</span></td>'+
        '<td><button class="link-btn tiny" data-action="download-annual-invoice" data-id="'+inv.id+'">Download</button> '+voidBtn+'</td></tr>'+
        ((STATE.voidingInvoice && STATE.voidingInvoice.type==='annual' && STATE.voidingInvoice.id===inv.id) ? '<tr><td colspan="8">'+renderVoidPanel()+'</td></tr>' : '');
    }).join('');
    var allRows = entRows+annRows;
    return '<div class="card">'+
      '<div class="card-title">Invoice History</div>'+
      '<div class="field-hint" style="margin-bottom:14px;">Every invoice ever issued to this client - Annual Invoices and New Hire / Promotion / Initial Roster invoices together, newest first. Each is re-downloadable exactly as issued. Voiding requires a reason and keeps the original visible here for the record; a corrected invoice issued afterward gets the next number in sequence. Tick Payment once the client has actually settled an entitlement invoice - that\'s what Money Holding on New Hire Invoicing is based on, not just whether it was issued.</div>'+
      (allRows ? ('<div class="table-wrap"><table class="data-table">'+
        '<thead><tr><th>Invoice #</th><th>Type</th><th>Issued</th><th>Employees</th><th>Amount</th><th>Status</th><th>Payment</th><th></th></tr></thead>'+
        '<tbody>'+allRows+'</tbody></table></div>')
        : '<div class="empty-state">No invoices issued yet.</div>')+
    '</div>';
  }

  function renderAdminReports(){
    var currentYearValue = currentReportYearValue();
    var currentMonthValue = currentReportMonthValue();
    var period = resolveReportPeriod(currentYearValue, currentMonthValue);
    var report = buildPeriodReport(STATE.claims, period.startDate, period.endDate);
    var yearOptions = buildReportYearOptions(STATE.claims);
    var isYtd = currentYearValue==='ytd';
    var searchQuery = (STATE.reportSearchQuery||'').trim().toLowerCase();
    var matchedCategories = searchQuery ? STATE.benefits.filter(function(b){ return b.toLowerCase().indexOf(searchQuery)!==-1; }) : [];
    var categoryScoped = matchedCategories.length > 0;

    var empRowData = STATE.profiles.filter(function(p){ return p.role==='user'; }).map(function(p){
      var r = report.byEmployee[p.id]||{count:0,total:0,categories:{},claims:[]};
      var allCatKeys = Object.keys(r.categories||{});
      var nameMatches = searchQuery && p.name.toLowerCase().indexOf(searchQuery)!==-1;
      return {p:p, r:r, allCatKeys:allCatKeys, nameMatches:nameMatches};
    }).filter(function(row){
      if(!searchQuery) return true;
      if(row.nameMatches) return true;
      if(categoryScoped){ return row.allCatKeys.some(function(cat){ return matchedCategories.indexOf(cat)!==-1; }); }
      return false;
    }).map(function(row){
      var showCatKeys = (categoryScoped && !row.nameMatches) ? row.allCatKeys.filter(function(cat){ return matchedCategories.indexOf(cat)!==-1; }) : row.allCatKeys;
      var displayCount = 0, displayTotal = 0;
      showCatKeys.forEach(function(cat){ displayCount += row.r.categories[cat].count; displayTotal += row.r.categories[cat].total; });
      var pct = row.p.annual_allocation>0 ? (displayTotal/row.p.annual_allocation*100) : 0;
      // Same category-search scoping applied to the underlying claim list so
      // the expandable detail view only ever shows what the summary row's
      // count/total already reflect - searching "gym" and expanding a match
      // won't suddenly reveal that employee's unrelated medical claims too.
      var claims = (categoryScoped && !row.nameMatches)
        ? (row.r.claims||[]).filter(function(cl){ return showCatKeys.indexOf(cl.category)!==-1; })
        : (row.r.claims||[]);
      return {empId:row.p.id, name:row.p.name, count:displayCount, total:displayTotal, allocation:row.p.annual_allocation, pct:pct, claims:claims};
    });
    empRowData = sortRows(empRowData, STATE.reportSortColumn, STATE.reportSortDirection, {
      count: function(r){ return r.count; }, total: function(r){ return r.total; },
      allocation: function(r){ return r.allocation; }, pct: function(r){ return r.pct; }
    });
    var empRows = empRowData.map(function(r){
      var isOpen = !!STATE.reportExpandedEmployees[r.empId];
      var toggleCell = r.claims.length
        ? '<button class="link-btn" style="text-decoration:none;" data-action="toggle-report-employee-detail" data-emp-id="'+r.empId+'">'+(isOpen?'▼ Hide':'▶ Details')+'</button>'
        : '<span class="tiny muted">&mdash;</span>';
      var mainRow = '<tr><td>'+escapeHtml(r.name)+'</td><td>'+r.count+'</td><td>'+fmtMoney(r.total)+'</td><td>'+fmtMoney(r.allocation)+'</td><td>'+r.pct.toFixed(1)+'%</td><td class="tiny">'+toggleCell+'</td></tr>';
      if(!isOpen || !r.claims.length) return mainRow;
      var claimRows = r.claims.map(function(cl, i){
        return '<tr><td>'+(i+1)+'</td><td>'+escapeHtml(cl.category)+'</td><td>'+fmtDateDMY(cl.receiptDate)+'</td><td>'+fmtMoney(cl.amount)+'</td></tr>';
      }).join('');
      var detailRow = '<tr class="claim-detail-row"><td colspan="6"><div class="claim-detail-wrap"><table class="claim-detail-table">'+
        '<thead><tr><th>Claim #</th><th>Category</th><th>Receipt Date</th><th>Amount</th></tr></thead><tbody>'+
        claimRows+
        '<tr class="total-row"><td colspan="3">Total &middot; '+r.claims.length+' claim'+(r.claims.length===1?'':'s')+'</td><td>'+fmtMoney(r.total)+'</td></tr>'+
        '</tbody></table></div></td></tr>';
      return mainRow+detailRow;
    }).join('');

    var rejSearchQuery = (STATE.rejectedSearchQuery||'').trim().toLowerCase();
    var rejRowData = Object.keys(report.byEmployeeRejected).map(function(empId){
      var r = report.byEmployeeRejected[empId];
      var reasonBreakdown = Object.keys(r.reasons).map(function(reason){
        var n = r.reasons[reason];
        return escapeHtml(reason)+(n>1 ? ' x'+n : '');
      }).join(', ');
      return {name:r.name, count:r.count, total:r.total, reasonBreakdown:reasonBreakdown};
    }).filter(function(row){
      if(!rejSearchQuery) return true;
      if(row.name.toLowerCase().indexOf(rejSearchQuery)!==-1) return true;
      return row.reasonBreakdown.toLowerCase().indexOf(rejSearchQuery)!==-1;
    });
    rejRowData = sortRows(rejRowData, STATE.rejectedSortColumn, STATE.rejectedSortDirection, {
      count: function(r){ return r.count; }, total: function(r){ return r.total; }
    });
    var rejectedRows = rejRowData.map(function(r){
      return '<tr><td>'+escapeHtml(r.name)+'</td><td>'+r.count+'</td><td>'+fmtMoney(r.total)+'</td><td class="tiny">'+r.reasonBreakdown+'</td></tr>';
    }).join('');

    var clientNameCell = STATE.editingClientName
      ? '<input type="text" maxlength="120" style="width:180px" id="client-name-input" value="'+escapeHtml(getClientCompanyName())+'"/> <button class="btn btn-sm btn-primary" data-action="save-client-name">Save</button>'
      : '<span class="muted">Prepared for: '+escapeHtml(getClientCompanyName())+'</span> <button class="link-btn" data-action="edit-client-name">Edit</button>';

    var currentViewMode = reportViewMode();
    var viewModeToggle = (benefitYearStartMonth()!==1) ? ('<div class="tiny muted" style="margin-bottom:8px;">View: '+
        '<button class="link-btn" data-action="set-report-view-mode" data-mode="benefit" style="font-weight:'+(currentViewMode==='benefit'?'700':'400')+';">Benefit Year</button> &middot; '+
        '<button class="link-btn" data-action="set-report-view-mode" data-mode="calendar" style="font-weight:'+(currentViewMode==='calendar'?'700':'400')+';">Calendar Year (Jan-Dec)</button></div>') : '';

    return ''+
    '<div class="card"><div class="card-title">Monthly Utilisation Report</div>'+
      viewModeToggle+
      '<div class="report-controls">'+
        '<select data-action="set-report-month" '+(isYtd?'disabled':'')+'>'+reportMonthSequence().map(function(actualMo,slot){ return '<option value="'+slot+'" '+(slot===currentMonthValue?'selected':'')+'>'+REPORT_MONTH_NAMES[actualMo]+'</option>'; }).join('')+'</select>'+
        '<select data-action="set-report-year">'+yearOptions.map(function(o){ return '<option value="'+o.value+'" '+(o.value===currentYearValue?'selected':'')+'>'+escapeHtml(o.label)+'</option>'; }).join('')+'</select>'+
        '<button class="btn btn-ghost btn-sm" data-action="export-report">Export to Excel</button>'+
        '<label class="pdf-detail-check"><input type="checkbox" id="pdf-include-details" '+(STATE.pdfIncludeClaimDetails?'checked':'')+'/> Include claim details</label>'+
        '<button class="btn btn-ghost btn-sm" data-action="export-report-pdf">Export to PDF for HR</button>'+
      '</div>'+
      '<div class="field-hint" style="margin:10px 0;">'+clientNameCell+'</div>'+
      '<div class="report-summary">'+escapeHtml(period.label)+' - Total claimed (approved): <strong>'+fmtMoney(report.totalClaimed)+'</strong> across <strong>'+report.totalCount+'</strong> submission(s). '+
        '<strong>'+report.totalRejectedCount+'</strong> submission(s) rejected, totaling <strong>'+fmtMoney(report.totalRejectedAmount)+'</strong>.</div>'+
    '</div>'+
    '<div class="card"><div class="card-title">By Employee</div>'+
      '<input type="text" id="report-search-input" class="search-input" placeholder="Search by employee name or benefit category..." value="'+escapeHtml(STATE.reportSearchQuery||'')+'" style="margin-bottom:12px;" />'+
      (categoryScoped ? '<div class="muted small" style="margin-bottom:10px;">Showing # Claims and Amount Claimed for '+matchedCategories.map(escapeHtml).join(', ')+' only.</div>' : '')+
      '<div class="table-wrap"><table class="data-table">'+
      '<thead><tr><th>Employee</th>'+
        '<th class="sortable-th" data-action="sort-report-emp" data-column="count"># Claims'+sortArrow('count',STATE.reportSortColumn,STATE.reportSortDirection)+'</th>'+
        '<th class="sortable-th" data-action="sort-report-emp" data-column="total">Amount Claimed'+sortArrow('total',STATE.reportSortColumn,STATE.reportSortDirection)+'</th>'+
        '<th class="sortable-th" data-action="sort-report-emp" data-column="allocation">Entitlement (SGD)'+sortArrow('allocation',STATE.reportSortColumn,STATE.reportSortDirection)+'</th>'+
        '<th class="sortable-th" data-action="sort-report-emp" data-column="pct">Utilisation %'+sortArrow('pct',STATE.reportSortColumn,STATE.reportSortDirection)+'</th>'+
        '<th>Details</th></tr></thead><tbody>'+empRows+'</tbody></table></div>'+
    '</div>'+
    '<div class="card"><div class="card-title">Rejected Claims</div>'+
      '<input type="text" id="rejected-search-input" class="search-input" placeholder="Search by employee name or reason..." value="'+escapeHtml(STATE.rejectedSearchQuery||'')+'" style="margin-bottom:12px;" />'+
      (rejectedRows ? '<div class="table-wrap"><table class="data-table">'+
        '<thead><tr><th>Employee</th>'+
          '<th class="sortable-th" data-action="sort-report-rejected" data-column="count"># Claims Rejected'+sortArrow('count',STATE.rejectedSortColumn,STATE.rejectedSortDirection)+'</th>'+
          '<th class="sortable-th" data-action="sort-report-rejected" data-column="total">Amount Rejected'+sortArrow('total',STATE.rejectedSortColumn,STATE.rejectedSortDirection)+'</th>'+
          '<th>Reasons</th></tr></thead><tbody>'+rejectedRows+'</tbody></table></div>'
        : '<div class="empty-state">No rejected claims for this period.</div>')+
    '</div>';
  }

  function drawBarChart(doc, x, y, width, height, data, opts){
    opts = opts||{};
    var maxVal = Math.max.apply(null, data.map(function(d){ return d.value; })) || 1;
    var barCount = data.length;
    if(!barCount) return;
    var gap = 6;
    var barWidth = Math.min(28, (width - gap*(barCount-1)) / barCount);
    var usedWidth = barWidth*barCount + gap*(barCount-1);
    var startX = x + (width-usedWidth)/2;
    var chartBottom = y + height;
    var barColor = opts.barColor || [19,78,74];
    doc.setDrawColor(210,210,210);
    doc.line(x, chartBottom, x+width, chartBottom);
    data.forEach(function(d, i){
      var barHeight = (d.value/maxVal) * (height-24);
      var barX = startX + i*(barWidth+gap);
      var barY = chartBottom - barHeight;
      doc.setFillColor(barColor[0],barColor[1],barColor[2]);
      doc.rect(barX, barY, barWidth, barHeight, 'F');
      doc.setFontSize(7);
      doc.setTextColor(90,90,90);
      var valueLabel = opts.valueFormat ? opts.valueFormat(d.value) : String(d.value);
      doc.text(valueLabel, barX+barWidth/2, barY-3, {align:'center'});
      doc.setFontSize(7);
      doc.setTextColor(40,40,40);
      var labelLines = doc.splitTextToSize(d.label, barWidth+gap);
      doc.text(labelLines.slice(0,2), barX+barWidth/2, chartBottom+8, {align:'center'});
    });
  }

  function exportReportExcel(){
    if(typeof XLSX==='undefined'){ showToast('Excel export library did not load (needs an internet connection).', 'error'); return; }
    var yearValue = currentReportYearValue();
    var monthValue = currentReportMonthValue();
    var period = resolveReportPeriod(yearValue, monthValue);
    var report = buildPeriodReport(STATE.claims, period.startDate, period.endDate);

    var summaryData = [['Utilisation Report'],[period.label],[],
      ['Total Claimed (Approved)', Number(report.totalClaimed.toFixed(2))],
      ['Total Submissions', report.totalCount],
      ['Total Rejected Submissions', report.totalRejectedCount],
      ['Total Rejected Amount', Number(report.totalRejectedAmount.toFixed(2))]];
    var catData = [['Category','Number of Claims','Amount Claimed']];
    STATE.benefits.forEach(function(b){ var r=report.byCategory[b]||{count:0,total:0}; catData.push([b, r.count, Number(r.total.toFixed(2))]); });
    var empData = [['Employee','PayNow Mobile','Number of Claims','Amount Claimed','Entitlement (SGD)','Utilisation %']];
    STATE.profiles.filter(function(p){ return p.role==='user'; }).forEach(function(p){
      var r = report.byEmployee[p.id]||{count:0,total:0};
      var pct = p.annual_allocation>0 ? (r.total/p.annual_allocation*100) : 0;
      empData.push([p.name, p.paynow_mobile||'', r.count, Number(r.total.toFixed(2)), Number(p.annual_allocation), Number(pct.toFixed(1))]);
    });
    var rejData = [['Employee','Category','Amount','Reason']];
    report.rejectedClaims.forEach(function(rc){ rejData.push([rc.employeeName, rc.category, Number(rc.amount.toFixed(2)), rc.reason]); });

    try{
      var wb = XLSX.utils.book_new();
      var wsSummary = XLSX.utils.aoa_to_sheet(summaryData); wsSummary['!cols']=[{wch:28},{wch:16}];
      var wsCat = XLSX.utils.aoa_to_sheet(catData); wsCat['!cols']=[{wch:24},{wch:16},{wch:14}];
      var wsEmp = XLSX.utils.aoa_to_sheet(empData); wsEmp['!cols']=[{wch:24},{wch:16},{wch:14},{wch:14},{wch:16},{wch:14}];
      var wsRej = XLSX.utils.aoa_to_sheet(rejData); wsRej['!cols']=[{wch:24},{wch:18},{wch:12},{wch:40}];
      XLSX.utils.book_append_sheet(wb, wsSummary, 'Summary');
      XLSX.utils.book_append_sheet(wb, wsCat, 'By Category');
      XLSX.utils.book_append_sheet(wb, wsEmp, 'By Employee');
      XLSX.utils.book_append_sheet(wb, wsRej, 'Rejected Claims');
      XLSX.writeFile(wb, 'utilisation-report-'+period.fileSuffix+'.xlsx');
    }catch(err){
      console.error(err);
      showToast('Something went wrong building the Excel file.', 'error');
    }
  }

  function exportReportPDF(){
    if(typeof window.jspdf==='undefined' || !window.jspdf.jsPDF){ showToast('PDF export library did not load (needs an internet connection).', 'error'); return; }
    var yearValue = currentReportYearValue();
    var monthValue = currentReportMonthValue();
    var period = resolveReportPeriod(yearValue, monthValue);
    var report = buildPeriodReport(STATE.claims, period.startDate, period.endDate);
    var periodLabel = period.label;
    var employees = STATE.profiles.filter(function(p){ return p.role==='user'; });
    // Off by default (matches the on-screen checkbox's default) - the PDF
    // stays a compact one-line-per-employee summary unless HR explicitly
    // ticks "Include claim details" before exporting, in which case every
    // employee's individual claims are itemised in the By Employee table.
    var includeDetails = !!STATE.pdfIncludeClaimDetails;

    var empStats = employees.map(function(p){
      var r = report.byEmployee[p.id]||{count:0,total:0,claims:[]};
      var pct = p.annual_allocation>0 ? (r.total/p.annual_allocation*100) : 0;
      return {name:p.name, count:r.count, total:r.total, allocation:Number(p.annual_allocation)||0, pct:pct, claims:r.claims||[]};
    });
    var totalEntitlementPool = employees.reduce(function(s,p){ return s+(Number(p.annual_allocation)||0); }, 0);
    var overallUtilPct = totalEntitlementPool>0 ? (report.totalClaimed/totalEntitlementPool*100) : 0;
    var zeroUsageCount = empStats.filter(function(e){ return e.count===0; }).length;
    var highUsageCount = empStats.filter(function(e){ return e.pct>=80; }).length;
    var categoryTotals = STATE.benefits.map(function(b){ return {name:b, total:(report.byCategory[b]||{total:0}).total}; }).sort(function(a,b){ return b.total-a.total; });
    var topCategory = categoryTotals.length && categoryTotals[0].total>0 ? categoryTotals[0] : null;
    var rejectionReasonCounts = {};
    report.rejectedClaims.forEach(function(rc){ rejectionReasonCounts[rc.reason] = (rejectionReasonCounts[rc.reason]||0)+1; });
    var topRejectionReason = Object.keys(rejectionReasonCounts).sort(function(a,b){ return rejectionReasonCounts[b]-rejectionReasonCounts[a]; })[0];
    var totalSubmissions = report.totalCount + report.totalRejectedCount;
    var rejectionRate = totalSubmissions>0 ? (report.totalRejectedCount/totalSubmissions*100) : 0;

    try{
      var doc = new window.jspdf.jsPDF({unit:'mm', format:'a4'});
      var pageWidth = doc.internal.pageSize.getWidth();
      var pageHeight = doc.internal.pageSize.getHeight();
      var margin = 15;
      var brandColor = CLIENT_COLOR_RGB;
      // Light-touch header (small logo, thin accent rule, tick-mark section
      // headings) rather than a full solid-colour banner -- matches the
      // entitlement invoice's styling so every PDF in the portal reads as
      // one family. This report uses the CLIENT's own colour throughout
      // since it's a report prepared FOR the client (by Cresco), not billed by Cresco.
      var sectionHeading = function(text, y){
        doc.setFillColor(brandColor[0],brandColor[1],brandColor[2]);
        doc.rect(margin, y-4, 2.2, 4.6, 'F');
        doc.setFontSize(12); doc.setTextColor(40,40,40);
        doc.text(text, margin+5, y);
      };

      /* ---- Page 1: Cover, Key Metrics, Key Insights ---- */
      var logoW = 34, logoH = logoW*CRESCO_LOGO_RATIO;
      doc.addImage(CRESCO_LOGO_DATA_URI, 'PNG', margin, 10, logoW, logoH);
      doc.setTextColor(50,50,50);
      doc.setFontSize(15);
      doc.text('Flex Benefits Portal', pageWidth-margin, 16, {align:'right'});
      doc.setFontSize(9);
      doc.setTextColor(120,120,120);
      doc.text('Monthly Utilisation Report - '+periodLabel, pageWidth-margin, 22, {align:'right'});
      doc.text('Prepared by Cresco for '+getClientCompanyName(), pageWidth-margin, 28, {align:'right'});
      doc.setDrawColor(brandColor[0],brandColor[1],brandColor[2]);
      doc.setLineWidth(0.8);
      doc.line(margin, 34, pageWidth-margin, 34);

      doc.setTextColor(40,40,40);
      doc.setFontSize(9);
      doc.text('Generated '+fmtDate(todayStr()), margin, 42);

      var cy = 50;
      sectionHeading('Key Metrics', cy);
      var metrics = [
        ['Total Claimed (Approved)', fmtMoney(report.totalClaimed)+' SGD'],
        ['Total Entitlement Pool', fmtMoney(totalEntitlementPool)+' SGD'],
        ['Overall Utilisation', overallUtilPct.toFixed(1)+'%'],
        ['Approved Submissions', String(report.totalCount)],
        ['Rejected Submissions', report.totalRejectedCount+' ('+rejectionRate.toFixed(1)+'% rejection rate)'],
        ['Employees With Zero Usage', zeroUsageCount+' of '+employees.length],
        ['Employees Above 80% Utilisation', String(highUsageCount)]
      ];
      doc.autoTable({
        startY: cy+4, margin:{left:margin, right:margin},
        body: metrics, theme:'plain', styles:{fontSize:10, cellPadding:1.5},
        columnStyles:{0:{fontStyle:'bold', cellWidth:85}}
      });
      cy = doc.lastAutoTable.finalY + 10;

      sectionHeading('Key Insights', cy); cy += 6;
      doc.setFontSize(10); doc.setTextColor(40,40,40);
      var insights = [];
      if(topCategory) insights.push('The most utilised benefit this period is '+topCategory.name+', accounting for '+fmtMoney(topCategory.total)+' SGD.');
      if(zeroUsageCount>0) insights.push(zeroUsageCount+' employee(s) submitted no claims this period - consider a reminder or awareness push.');
      if(highUsageCount>0) insights.push(highUsageCount+' employee(s) have used 80% or more of their entitlement this period.');
      if(topRejectionReason) insights.push('The most common rejection reason is "'+topRejectionReason+'" ('+rejectionReasonCounts[topRejectionReason]+' occurrence(s)).');
      if(!insights.length) insights.push('No notable trends to highlight for this period.');
      insights.forEach(function(line){
        var split = doc.splitTextToSize('- '+line, pageWidth-margin*2-4);
        doc.text(split, margin, cy);
        cy += split.length*5 + 2;
      });

      var catChartData = STATE.benefits.map(function(b){
        var r = report.byCategory[b]||{count:0,total:0};
        return {label:b, value:Number(r.total.toFixed(2))};
      });
      cy += 8;
      if(cy > pageHeight-75){ doc.addPage(); cy = 20; }
      sectionHeading('Amount Claimed by Category', cy);
      drawBarChart(doc, margin, cy+6, pageWidth-margin*2, 55, catChartData, {valueFormat:function(v){ return fmtMoney(v); }, barColor:brandColor});

      /* ---- Page: Category + Employee tables ---- */
      doc.addPage();
      sectionHeading('By Benefit Category', 18);
      var catRows = STATE.benefits.map(function(b){
        var r = report.byCategory[b]||{count:0,total:0};
        return [b, String(r.count), fmtMoney(r.total)];
      });
      doc.autoTable({
        startY: 24, margin:{left:margin, right:margin},
        head:[['Category','# Claims','Amount Claimed (SGD)']], body: catRows,
        theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:brandColor, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
      });

      var empSorted = empStats.slice().sort(function(a,b){ return b.pct-a.pct; });
      var empChartTop = doc.lastAutoTable.finalY + 14;
      sectionHeading('Top Employees by Amount Claimed', empChartTop);
      var topEmp = empStats.slice().sort(function(a,b){ return b.total-a.total; }).slice(0,8)
        .map(function(e){ return {label:e.name, value:Number(e.total.toFixed(2))}; });
      if(topEmp.length){
        drawBarChart(doc, margin, empChartTop+6, pageWidth-margin*2, 55, topEmp, {valueFormat:function(v){ return fmtMoney(v); }, barColor:brandColor});
      } else {
        doc.setFontSize(9); doc.setTextColor(120,120,120);
        doc.text('No approved claims this period.', margin, empChartTop+15);
      }

      /* ---- Page: Full employee table, sorted by utilisation ---- */
      doc.addPage();
      sectionHeading('By Employee - '+periodLabel, 18);
      var empRows = empSorted.map(function(e){
        return [e.name, String(e.count), fmtMoney(e.total), fmtMoney(e.allocation), e.pct.toFixed(1)+'%'];
      });
      doc.autoTable({
        startY: 24, margin:{left:margin, right:margin},
        head:[['Employee','# Claims','Amount Claimed (SGD)','Entitlement (SGD)','Utilisation %']], body: empRows,
        theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:brandColor, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
      });

      /* ---- Page(s): Claim Detail - only when "Include claim details" is
         ticked. One itemised table per employee (skipping anyone with zero
         claims, since they add nothing here and the summary above already
         covers them), mirroring the on-screen expand view exactly. ---- */
      if(includeDetails){
        doc.addPage();
        sectionHeading('Claim Detail - '+periodLabel, 18);
        var withClaims = empSorted.filter(function(e){ return e.claims && e.claims.length; });
        if(withClaims.length){
          var dcy = 24;
          withClaims.forEach(function(e){
            if(dcy > pageHeight-40){ doc.addPage(); dcy = 20; }
            doc.setFontSize(10); doc.setTextColor(40,40,40); doc.setFont(undefined,'bold');
            doc.text(e.name, margin, dcy);
            doc.setFont(undefined,'normal');
            var claimRows = e.claims.map(function(cl, i){
              return [String(i+1), cl.category, fmtDateDMY(cl.receiptDate), fmtMoney(cl.amount)];
            });
            claimRows.push(['', '', 'Total - '+e.claims.length+' claim'+(e.claims.length===1?'':'s'), fmtMoney(e.total)]);
            doc.autoTable({
              startY: dcy+3, margin:{left:margin, right:margin},
              head:[['Claim #','Category','Receipt Date','Amount (SGD)']], body: claimRows,
              theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:brandColor, lineWidth:0.3},
              styles:{fontSize:8.5, lineColor:[225,225,225]},
              didParseCell: function(data){
                if(data.row.index===claimRows.length-1){ data.cell.styles.fontStyle='bold'; }
              }
            });
            dcy = doc.lastAutoTable.finalY + 10;
          });
        } else {
          doc.setFontSize(10); doc.setTextColor(120,120,120);
          doc.text('No approved claims this period.', margin, 26);
        }
      }

      /* ---- Page: Rejected claims ---- */
      doc.addPage();
      sectionHeading('Rejected Claims - '+periodLabel, 18);
      if(report.rejectedClaims.length){
        var rejRows = report.rejectedClaims.map(function(rc){
          return [rc.employeeName, rc.category, fmtMoney(rc.amount), rc.reason];
        });
        doc.autoTable({
          startY: 24, margin:{left:margin, right:margin},
          head:[['Employee','Category','Amount (SGD)','Reason']], body: rejRows,
          theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:brandColor, lineWidth:0.3}, styles:{fontSize:8, lineColor:[225,225,225]},
          columnStyles:{3:{cellWidth:70}}
        });
      } else {
        doc.setFontSize(10); doc.setTextColor(120,120,120);
        doc.text('No rejected claims this period.', margin, 30);
      }

      doc.save('flex-benefits-hr-report-'+period.fileSuffix+'.pdf');
    }catch(err){
      console.error(err);
      showToast('Could not generate the PDF. Check the console for details.', 'error');
    }
  }

  // EDIT PER CLIENT ONLY IF CRESCO'S OWN BANKING CHANGES - this is Cresco's
  // remittance account, shown on every invoice Cresco issues (Annual and
  // Entitlement/New Hire alike), regardless of which client is being billed.
  var CRESCO_BANK_DETAILS = {
    accountName: 'Cresco Insurance Agency Pte Ltd',
    bank: 'DBS Bank Ltd',
    accountType: 'DBS Corporate Current Account',
    accountNumber: '106-900974-0'
  };

  // Shared "Payment Details" block drawn near the bottom of every invoice
  // PDF, right under the invoice summary/total - reused by both
  // exportInvoicePDF (Annual) and exportEntitlementInvoicePDF (New Hire/
  // Promotion/Initial Roster) so a banking change only needs editing once,
  // above. Returns the y position after the block so callers can continue
  // laying out content below it if needed.
  function drawPaymentDetailsBlock(doc, margin, pageWidth, y){
    doc.setDrawColor(210,210,210);
    doc.setLineWidth(0.2);
    doc.line(margin, y, pageWidth-margin, y);
    y += 5;
    doc.setFontSize(9); doc.setTextColor(40,40,40);
    doc.text('Payment Details', margin, y);
    y += 5;
    doc.setFontSize(8.5); doc.setTextColor(90,90,90);
    doc.text('Payable to: '+CRESCO_BANK_DETAILS.accountName, margin, y); y += 4;
    doc.text(CRESCO_BANK_DETAILS.bank+' - '+CRESCO_BANK_DETAILS.accountType, margin, y); y += 4;
    doc.text('Account No: '+CRESCO_BANK_DETAILS.accountNumber, margin, y); y += 4;
    return y;
  }

  // opts: {inv (already waiver-applied), year, invoiceNumber, invoiceDate, preview (bool)}
  // preview=true draws a "DRAFT - NOT YET ISSUED" watermark instead of a real
  // invoice number, for the Preview action; Issue and Invoice History
  // downloads pass preview=false with the real assigned number.
  function exportInvoicePDF(opts){
    if(typeof window.jspdf==='undefined' || !window.jspdf.jsPDF){ showToast('PDF export library did not load (needs an internet connection).', 'error'); return; }
    var year = opts.year;
    var bounds = benefitYearBounds(year);
    var nextBounds = benefitYearBounds(year+1);
    var inv = opts.inv;
    var invoiceNumber = opts.preview ? 'DRAFT - NOT YET ISSUED' : opts.invoiceNumber;
    var invoiceDate = opts.invoiceDate;
    var adjustmentLabel = inv.adjustmentAmount>=0 ? 'Additional Headcount Charge' : 'Headcount Reduction Credit';
    var adjWaiver = inv.adjustmentWaiver || {status:'normal'};
    var baseWaiver = inv.baseWaiver || {status:'normal'};
    var adjWaiverNote = adjWaiver.status!=='normal' ? (' ['+(adjWaiver.status==='waived'?'Waived off':'Adjusted')+(adjWaiver.reason?' - '+adjWaiver.reason:'')+']') : '';
    var baseWaiverNote = baseWaiver.status!=='normal' ? (' ['+(baseWaiver.status==='waived'?'Waived off':'Adjusted')+(baseWaiver.reason?' - '+baseWaiver.reason:'')+']') : '';
    var adjustmentValueText = (adjWaiver.status!=='normal' && inv.calculatedAdjustmentAmount!=null)
      ? ('Calculated '+fmtMoney(Math.abs(inv.calculatedAdjustmentAmount))+' -> Billed '+fmtMoney(Math.abs(inv.adjustmentAmount))+adjWaiverNote)
      : fmtMoney(Math.abs(inv.adjustmentAmount));
    var baseChargeValueText = (baseWaiver.status!=='normal' && inv.calculatedBaseHeadcountCharge!=null)
      ? ('Calculated '+fmtMoney(inv.calculatedBaseHeadcountCharge)+' -> Billed '+fmtMoney(inv.baseHeadcountCharge)+baseWaiverNote)
      : fmtMoney(inv.baseHeadcountCharge);

    try{
      var doc = new window.jspdf.jsPDF({unit:'mm', format:'a4'});
      var pageWidth = doc.internal.pageSize.getWidth();
      var pageHeight = doc.internal.pageSize.getHeight();
      var margin = 15;
      var brandColor = CRESCO_COLOR_RGB;
      // Light-touch header (small logo, thin accent rule, tick-mark section
      // headings) instead of a full solid-colour banner -- per Tin's
      // feedback that the old banner read too heavy. Matches the
      // entitlement invoice's look so every Cresco-issued invoice is
      // visually one family. Always Cresco's own colour/logo here, since
      // Cresco is the one issuing this invoice regardless of which client
      // it's billed to.
      var accent = brandColor;
      var sectionHeading = function(text, y){
        doc.setFillColor(accent[0],accent[1],accent[2]);
        doc.rect(margin, y-4, 2.2, 4.6, 'F');
        doc.setFontSize(12); doc.setTextColor(40,40,40);
        doc.text(text, margin+5, y);
      };

      var logoW = 34, logoH = logoW*CRESCO_LOGO_RATIO;
      doc.addImage(CRESCO_LOGO_DATA_URI, 'PNG', margin, 10, logoW, logoH);
      doc.setTextColor(50,50,50);
      doc.setFontSize(15);
      doc.text('Annual Invoice', pageWidth-margin, 16, {align:'right'});
      doc.setFontSize(9);
      doc.setTextColor(120,120,120);
      doc.text('Headcount Adjustment & Credit Note', pageWidth-margin, 22, {align:'right'});
      doc.text('Flex Benefits Portal by Cresco', pageWidth-margin, 28, {align:'right'});
      doc.setDrawColor(accent[0],accent[1],accent[2]);
      doc.setLineWidth(0.8);
      doc.line(margin, 33, pageWidth-margin, 33);

      doc.setTextColor(40,40,40);
      doc.setFontSize(9);
      var iy = 41;
      doc.text('Invoice Date: '+invoiceDate, margin, iy);
      if(opts.preview){ doc.setTextColor(200,120,0); doc.text('Invoice No: '+invoiceNumber, margin, iy+6); doc.setTextColor(40,40,40); }
      else { doc.text('Invoice No: '+invoiceNumber, margin, iy+6); }
      var headerY = iy+12;
      if(opts.supersedesNumber){ doc.setTextColor(120,120,120); doc.text('Supersedes voided invoice: '+opts.supersedesNumber, margin, headerY); doc.setTextColor(40,40,40); headerY += 6; }
      doc.text('Period Covered: '+fmtDateDMY(bounds.startStr)+' - '+fmtDateDMY(bounds.endStr), margin, headerY);

      var cy = headerY+10;
      sectionHeading('Headcount Adjustment (True-Up for '+year+')', cy);
      doc.autoTable({
        startY: cy+4, margin:{left:margin, right:margin},
        body: [
          ['Headcount as at '+fmtDateDMY(bounds.startStr), String(inv.startHeadcount)],
          ['Headcount as at '+fmtDateDMY(bounds.endStr), String(inv.endHeadcount)],
          ['Net Change', String(inv.headcountDelta)],
          ['Adjustment Units (Net Change / 2)', String(inv.adjustmentUnits)],
          ['Rate per Headcount per Year', fmtMoney(inv.rate)],
          [adjustmentLabel, adjustmentValueText]
        ],
        theme:'plain', styles:{fontSize:10, cellPadding:1.5},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}}
      });
      cy = doc.lastAutoTable.finalY + 10;

      sectionHeading('Headcount Charge for '+(year+1), cy);
      doc.autoTable({
        startY: cy+4, margin:{left:margin, right:margin},
        body: [
          ['Headcount as at '+fmtDateDMY(nextBounds.startStr), String(inv.newYearHeadcount)],
          ['Rate per Headcount per Year', fmtMoney(inv.rate)],
          ['Base Headcount Charge', baseChargeValueText],
          ['Total Headcount Charge (Base + Adjustment)', fmtMoney(inv.totalHeadcountCharge)]
        ],
        theme:'plain', styles:{fontSize:10, cellPadding:1.5},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}}
      });
      cy = doc.lastAutoTable.finalY + 10;

      sectionHeading('Unutilised Benefit (Credit Note)', cy);
      doc.autoTable({
        startY: cy+4, margin:{left:margin, right:margin},
        body: [
          ['Total Entitlement Pool for '+year, fmtMoney(inv.totalEntitlementPool)],
          ['Total Approved Claims for '+year, fmtMoney(inv.totalApprovedForYear)],
          ['Total Unutilised Amount', fmtMoney(inv.totalUnutilized)]
        ],
        theme:'plain', styles:{fontSize:10, cellPadding:1.5},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}}
      });
      cy = doc.lastAutoTable.finalY + 10;

      sectionHeading('Invoice Summary', cy);
      var annualSummaryBody = [
        ['Additional Headcount Charge', fmtMoney(inv.additionalCharge)],
        ['Base Headcount Charge for '+(year+1), fmtMoney(inv.baseHeadcountCharge)],
        ['Less: Credit Note (Unutilised + Headcount Reduction)', '-'+fmtMoney(inv.creditNoteAmount)],
        [inv.netAmount>=0?'Net Amount Due':'Net Credit Balance', fmtMoney(Math.abs(inv.netAmount))],
        ['Invoice Payable Amount', fmtMoney(inv.invoicePayableAmount)]
      ];
      doc.autoTable({
        startY: cy+4, margin:{left:margin, right:margin},
        body: annualSummaryBody,
        theme:'grid', styles:{fontSize:10, cellPadding:2, lineColor:[225,225,225]},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}},
        didParseCell: function(data){
          if(data.row.index===annualSummaryBody.length-1){ data.cell.styles.fontStyle='bold'; data.cell.styles.fillColor=[250,240,241]; }
        }
      });
      cy = doc.lastAutoTable.finalY + 9;
      doc.setFontSize(8); doc.setTextColor(120,120,120);
      var noteLines = doc.splitTextToSize('Note: Any credit note balance may be applied to offset the following year\'s flex benefit charges.', pageWidth-margin*2);
      doc.text(noteLines, margin, cy);
      cy += noteLines.length*4 + 4;
      // Payment Details always belongs on page 1 with the total, right next
      // to what the client is actually paying - the addPage() fallback below
      // is only a last-resort safety net for an unusually long note/waiver
      // block, not something the common case should ever hit.
      if(cy > pageHeight-30){ doc.addPage(); cy = 20; }
      drawPaymentDetailsBlock(doc, margin, pageWidth, cy);

      doc.addPage();
      sectionHeading('Headcount as at '+fmtDateDMY(nextBounds.startStr)+' - by Employee', 18);
      doc.setFontSize(9); doc.setTextColor(100,100,100);
      doc.text('Supporting detail for the base headcount charge above. '+inv.newYearHeadcountList.length+' employee(s) counted.', margin, 24);
      if(inv.newYearHeadcountList.length){
        var newYearHcRows = inv.newYearHeadcountList.map(function(e){ return [e.name, fmtMoney(e.allocation)]; });
        doc.autoTable({
          startY: 30, margin:{left:margin, right:margin},
          head:[['Employee','Annual Allocation (SGD)']], body: newYearHcRows,
          theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
        });
      } else {
        doc.setFontSize(10); doc.setTextColor(120,120,120);
        doc.text('No employees on record as at '+fmtDateDMY(nextBounds.startStr)+'.', margin, 34);
      }

      doc.addPage();
      sectionHeading('Headcount as at '+fmtDateDMY(bounds.startStr)+' - by Employee', 18);
      doc.setFontSize(9); doc.setTextColor(100,100,100);
      doc.text('Supporting detail for the headcount adjustment above. '+inv.startHeadcountList.length+' employee(s) counted.', margin, 24);
      if(inv.startHeadcountList.length){
        var startHcRows = inv.startHeadcountList.map(function(e){ return [e.name, fmtMoney(e.allocation)]; });
        doc.autoTable({
          startY: 30, margin:{left:margin, right:margin},
          head:[['Employee','Annual Allocation (SGD)']], body: startHcRows,
          theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
        });
      } else {
        doc.setFontSize(10); doc.setTextColor(120,120,120);
        doc.text('No employees on record as at '+fmtDateDMY(bounds.startStr)+'.', margin, 34);
      }

      doc.addPage();
      sectionHeading('New Joiners in '+year, 18);
      doc.setFontSize(9); doc.setTextColor(100,100,100);
      doc.text('Sorted by Effective Date - the joiners behind the net change above.', margin, 24);
      var joinersCy = 30;
      if(inv.newJoinersList.length){
        var joinerRows = inv.newJoinersList.map(function(e){ return [e.name, fmtDate(e.date), e.months+' of 12', fmtMoney(e.allocation), e.invoiceNumber||'(estimated, not yet invoiced)']; });
        doc.autoTable({
          startY: joinersCy, margin:{left:margin, right:margin},
          head:[['Employee','Effective Date','Months Billed','Prorated Entitlement (SGD)','Invoice #']], body: joinerRows,
          theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
        });
        joinersCy = doc.lastAutoTable.finalY + 16;
      } else {
        doc.setFontSize(10); doc.setTextColor(120,120,120);
        doc.text('No new joiners recorded in '+year+'.', margin, 34);
        joinersCy = 46;
      }

      sectionHeading('Terminations in '+year, joinersCy);
      doc.setFontSize(9); doc.setTextColor(100,100,100);
      doc.text('Sorted by Termination Date - the departures behind the net change above.', margin, joinersCy+6);
      if(inv.terminationsList.length){
        var terminationRows = inv.terminationsList.map(function(e){ return [e.name, fmtDate(e.date), e.months+' of 12', fmtMoney(e.allocation)]; });
        doc.autoTable({
          startY: joinersCy+12, margin:{left:margin, right:margin},
          head:[['Employee','Termination Date','Months Billed','Prorated Entitlement (SGD)']], body: terminationRows,
          theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
        });
      } else {
        doc.setFontSize(10); doc.setTextColor(120,120,120);
        doc.text('No terminations recorded in '+year+'.', margin, joinersCy+16);
      }

      doc.addPage();
      sectionHeading('Unutilised Amount by Employee - '+year, 18);
      doc.setFontSize(9); doc.setTextColor(100,100,100);
      doc.text('"Invoice #" traces this figure back to the New Hire/Promotion invoice that billed it - blank means the full or estimated allocation was used.', margin, 24);
      var empRows = inv.unutilizedByEmployee.map(function(e){
        return [e.name, fmtMoney(e.allocation), fmtMoney(e.approved), fmtMoney(e.unutilized), e.invoiceNumber||''];
      });
      doc.autoTable({
        startY: 29, margin:{left:margin, right:margin},
        head:[['Employee','Entitlement (SGD)','Approved Claims (SGD)','Unutilised (SGD)','Invoice #']], body: empRows,
        theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3}, styles:{fontSize:9, lineColor:[225,225,225]}
      });

      var fileTag = opts.preview ? ('DRAFT-'+year) : String(invoiceNumber).replace(/[^A-Za-z0-9-]/g,'');
      doc.save('flex-benefits-invoice-'+fileTag+'.pdf');
    }catch(err){
      console.error(err);
      showToast('Could not generate the invoice PDF. Check the console for details.', 'error');
    }
  }

  // Entitlement invoice PDF (New Hire / Promotion / Initial Roster). Per
  // Tin's feedback, this is issued BY Cresco but reads softer than the
  // Annual Invoice - the Cresco red is used as a thin accent (a rule under
  // the header, a small tick before each section heading, and the table
  // header outline) rather than a full solid banner.
  //
  // opts is either {invoiceRow, items} for an already-issued invoice
  // (Issue action or a re-download from history), or {preview:true,
  // previewData} for a live Preview - previewData is whatever
  // computeEntitlementInvoicePreview() returned, nothing saved or numbered.
  function exportEntitlementInvoicePDF(opts){
    if(typeof window.jspdf==='undefined' || !window.jspdf.jsPDF){ showToast('PDF export library did not load (needs an internet connection).', 'error'); return; }
    try{
      var isPreview = !!opts.preview;
      var previewData = opts.previewData;
      var invoiceRow = opts.invoiceRow;
      var invoiceType = isPreview ? previewData.invoiceType : invoiceRow.invoice_type;
      var isInitial = invoiceType==='initial';
      var invoiceNumber = isPreview ? 'DRAFT - NOT YET ISSUED' : invoiceRow.invoice_number;
      var invoiceDate = isPreview ? fmtDate(new Date().toISOString().slice(0,10)) : fmtDate((invoiceRow.issued_at||'').slice(0,10));

      var lines = isPreview
        ? previewData.lines.map(function(l){
            return {
              employeeName: l.item.employeeName, itemType: l.item.type, effectiveDate: l.item.effectiveDate,
              monthsBilled: l.item.months, prorated: l.selection.prorate,
              calculatedAmount: l.calculatedAmount, finalAmount: l.finalAmount,
              waiveStatus: l.selection.waiveStatus, waiveReason: l.selection.waiveReason
            };
          })
        : (opts.items||[]).map(function(it){
            return {
              employeeName: it.employee_name, itemType: it.item_type, effectiveDate: it.effective_date,
              monthsBilled: it.months_billed, prorated: it.prorated,
              calculatedAmount: it.calculated_amount, finalAmount: it.final_amount,
              waiveStatus: it.waived ? 'waived' : (it.override_amount!=null ? 'custom' : 'normal'), waiveReason: it.waived_reason
            };
          });
      var entitlementTotal = isPreview ? previewData.entitlementTotal : (Number(invoiceRow.entitlement_total)||0);
      var perPaxRate = isPreview ? (isInitial?previewData.rate:null) : invoiceRow.per_pax_rate;
      var perPaxTotal = isPreview ? previewData.perPaxTotal : (Number(invoiceRow.per_pax_total)||0);
      var headcountForPax = isPreview ? previewData.headcountForPax : lines.filter(function(l){ return l.itemType!=='promotion'; }).length;
      var totalAmount = isPreview ? previewData.totalAmount : (Number(invoiceRow.total_amount)||0);

      var doc = new window.jspdf.jsPDF({unit:'mm', format:'a4'});
      var pageWidth = doc.internal.pageSize.getWidth();
      var pageHeight = doc.internal.pageSize.getHeight();
      var margin = 15;
      var accent = CRESCO_COLOR_RGB;

      var logoW = 34, logoH = logoW*CRESCO_LOGO_RATIO;
      doc.addImage(CRESCO_LOGO_DATA_URI, 'PNG', margin, 10, logoW, logoH);
      doc.setTextColor(50,50,50);
      doc.setFontSize(15);
      doc.text(isInitial ? 'Initial Roster Invoice' : 'New Hire / Promotion Invoice', pageWidth-margin, 16, {align:'right'});
      doc.setFontSize(9);
      doc.setTextColor(120,120,120);
      doc.text('Entitlement Billing - Flex Benefits Portal by Cresco', pageWidth-margin, 22, {align:'right'});
      doc.setDrawColor(accent[0],accent[1],accent[2]);
      doc.setLineWidth(0.8);
      doc.line(margin, 27, pageWidth-margin, 27);

      doc.setTextColor(40,40,40);
      doc.setFontSize(9);
      var iy = 35;
      doc.text('Invoice Date: '+invoiceDate, margin, iy);
      if(isPreview){ doc.setTextColor(200,120,0); doc.text('Invoice No: '+invoiceNumber, margin, iy+6); doc.setTextColor(40,40,40); }
      else { doc.text('Invoice No: '+invoiceNumber, margin, iy+6); }
      var byLineY = iy+12;
      doc.text('Bill To: '+getClientCompanyName(), margin, byLineY);
      if(opts.supersedesNumber){ byLineY += 6; doc.setTextColor(120,120,120); doc.text('Supersedes voided invoice: '+opts.supersedesNumber, margin, byLineY); doc.setTextColor(40,40,40); }

      var sectionHeading = function(text, y){
        doc.setFillColor(accent[0],accent[1],accent[2]);
        doc.rect(margin, y-4, 2.2, 4.6, 'F');
        doc.setFontSize(12); doc.setTextColor(40,40,40);
        doc.text(text, margin+5, y);
      };

      var cy = byLineY+12;
      sectionHeading((isInitial?'Initial Roster - ':'')+'Entitlement Charges', cy);
      cy += 5;
      var rows = lines.map(function(l){
        var typeLabel = l.itemType==='promotion' ? 'Promotion' : (isInitial ? 'Initial Roster' : 'New Hire');
        var amountText = (l.waiveStatus && l.waiveStatus!=='normal')
          ? ('Calc. '+fmtMoney(l.calculatedAmount)+' -> '+(l.waiveStatus==='waived'?'Waived off':fmtMoney(l.finalAmount))+(l.waiveReason?' ('+l.waiveReason+')':''))
          : fmtMoney(l.finalAmount);
        return [l.employeeName, typeLabel, fmtDate(l.effectiveDate), l.prorated?(l.monthsBilled+' of 12'):'Full year', amountText];
      });
      doc.autoTable({
        startY: cy, margin:{left:margin, right:margin},
        head:[['Employee','Type','Effective Date','Billed As','Amount (SGD)']], body: rows.length?rows:[['No line items on this invoice.','','','','']],
        theme:'grid', headStyles:{fillColor:[247,247,247], textColor:[60,60,60], fontStyle:'bold', lineColor:accent, lineWidth:0.3},
        styles:{fontSize:9, lineColor:[225,225,225]}
      });
      cy = doc.lastAutoTable.finalY + 10;

      if(isInitial){
        sectionHeading('Headcount Establishment Charge', cy);
        cy += 5;
        doc.autoTable({
          startY: cy, margin:{left:margin, right:margin},
          body: [
            ['Employees Established', String(headcountForPax)],
            ['Rate per Head (one-time, flat - not prorated)', fmtMoney(perPaxRate)],
            ['Per-Pax Establishment Total', fmtMoney(perPaxTotal)]
          ],
          theme:'plain', styles:{fontSize:10, cellPadding:1.5},
          columnStyles:{0:{fontStyle:'bold', cellWidth:110}}
        });
        cy = doc.lastAutoTable.finalY + 10;
      }

      sectionHeading('Invoice Summary', cy);
      cy += 5;
      var summaryBody = [['Entitlement Total', fmtMoney(entitlementTotal)]];
      if(isInitial) summaryBody.push(['Per-Pax Establishment Total', fmtMoney(perPaxTotal)]);
      summaryBody.push(['Total Amount Due', fmtMoney(totalAmount)]);
      doc.autoTable({
        startY: cy, margin:{left:margin, right:margin},
        body: summaryBody,
        theme:'grid', headStyles:{fillColor:accent},
        styles:{fontSize:10, cellPadding:2},
        columnStyles:{0:{fontStyle:'bold', cellWidth:110}},
        didParseCell: function(data){
          if(data.row.index===summaryBody.length-1){ data.cell.styles.fontStyle='bold'; data.cell.styles.fillColor=[250,240,241]; }
        }
      });
      cy = doc.lastAutoTable.finalY + 9;
      doc.setFontSize(8); doc.setTextColor(120,120,120);
      var footNote = doc.splitTextToSize('This invoice bills entitlement dollars only - any headcount adjustment or base headcount charge for this client is billed separately on the Annual Invoice.'+(isPreview?' This is a draft preview - nothing has been saved or numbered yet.':''), pageWidth-margin*2);
      doc.text(footNote, margin, cy);
      cy += footNote.length*4 + 4;
      // Same as the Annual Invoice - Payment Details belongs on page 1 next
      // to the total; addPage() here is only a safety net for an unusually
      // long line-item list or waiver note, not the common case.
      if(cy > pageHeight-30){ doc.addPage(); cy = 20; }
      drawPaymentDetailsBlock(doc, margin, pageWidth, cy);

      var fileTag = isPreview ? 'DRAFT' : String(invoiceNumber).replace(/[^A-Za-z0-9-]/g,'');
      doc.save('entitlement-invoice-'+fileTag+'.pdf');
    }catch(err){
      console.error(err);
      showToast('Could not generate the invoice PDF. Check the console for details.', 'error');
    }
  }

  /* =========================================================
     ACTION HANDLERS - AUTH
  ========================================================== */
  function doLogin(form){
    var email = form.email.value.trim();
    var password = form.password.value;
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Logging in...';
    return withNetworkRetry(function(){ return supabase.auth.signInWithPassword({email:email, password:password}); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      STATE.authError=''; STATE.authInfo=''; STATE.session = res.data.session;
      STATE.loading = true; render();
      return loadProfileAndData().then(function(){
        STATE.loading=false;
        STATE.activeTab = STATE.profile.role==='admin' ? 'approvals' : 'dashboard';
        render();
        subscribeRealtime();
      }).catch(function(err){
        STATE.loading=false; STATE.session=null; STATE.profile=null;
        if(err.message!=='deactivated'){ STATE.authError = err.message; }
        render();
      });
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Login failed - please try again.';
      render();
    });
  }

  function doSignup(form){
    var email = form.email.value.trim();
    var password = form.password.value;
    var confirmPassword = form.confirmPassword.value;
    if(password !== confirmPassword){ STATE.authError='Passwords do not match.'; render(); return Promise.resolve(); }
    if(password.length < 6){ STATE.authError='Password must be at least 6 characters.'; render(); return Promise.resolve(); }
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Creating account...';
    var redirectTo = window.location.origin + window.location.pathname;
    return withNetworkRetry(function(){ return supabase.auth.signUp({email:email, password:password, options:{emailRedirectTo:redirectTo}}); }).then(function(res){
      if(res.error){
        var msg = res.error.message || '';
        if(/already registered|already exists|already been registered/i.test(msg)){
          STATE.authError = 'This email is already registered. Please log in instead.';
          showToast('This email is already registered - try logging in instead.', 'error');
        } else {
          STATE.authError = msg;
          render();
        }
        return;
      }
      var alreadyRegistered = res.data && res.data.user && Array.isArray(res.data.user.identities) && res.data.user.identities.length===0;
      if(alreadyRegistered){
        STATE.authError = 'This email is already registered. Please log in instead.';
        showToast('This email is already registered - try logging in instead.', 'error');
        return;
      }
      if(res.data.session){
        STATE.session = res.data.session;
        STATE.loading = true; render();
        return loadProfileAndData().then(function(){
          STATE.loading=false;
          STATE.activeTab = STATE.profile.role==='admin' ? 'approvals' : 'dashboard';
          render();
          subscribeRealtime();
        });
      }
      STATE.authView='login'; STATE.authError='';
      STATE.authInfo='Account created! Check your email to confirm, then log in.';
      render();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not create account - please try again.';
      render();
    });
  }

  function doForgotPassword(form){
    var email = form.email.value.trim();
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Sending...';
    STATE.authError = '';
    var redirectTo = window.location.origin + window.location.pathname;
    return withNetworkRetry(function(){ return withTimeout(supabase.auth.resetPasswordForEmail(email, {redirectTo:redirectTo}), 8000, 'Password reset request'); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      STATE.authView = 'forgot-sent'; STATE.authError = '';
      render();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not send reset email - please try again.';
      render();
    });
  }

  function doResetPassword(form){
    var password = form.password.value;
    var confirmPassword = form.confirmPassword.value;
    if(password !== confirmPassword){ STATE.authError = 'Passwords do not match.'; render(); return Promise.resolve(); }
    if(password.length < 6){ STATE.authError = 'Password must be at least 6 characters.'; render(); return Promise.resolve(); }
    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Saving...';
    STATE.authError = '';
    return withNetworkRetry(function(){ return supabase.auth.updateUser({password:password}); }).then(function(res){
      if(res.error){ STATE.authError = res.error.message; render(); return; }
      // Drop the temporary recovery session and send them to the ordinary
      // login screen to sign in fresh with the new password -- same pattern
      // as new-user signup, rather than silently carrying them into the app.
      STATE.passwordRecovery = false;
      STATE.authView = 'login'; STATE.authError = '';
      STATE.authInfo = 'Password updated - please log in with your new password.';
      render();
      return supabase.auth.signOut();
    }).catch(function(err){
      STATE.authError = (err && err.message) || 'Could not update password - please try again.';
      render();
    });
  }

  /* =========================================================
     ACTION HANDLERS - CLAIMS
  ========================================================== */
  function openReceiptModal(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    if(!claim || !claim.receipt_path) return;
    supabase.storage.from('receipts').createSignedUrl(claim.receipt_path, 120).then(function(res){
      if(res.error){ showToast('Could not load receipt.', 'error'); return; }
      STATE.modal = {type:'image', src:res.data.signedUrl, title:claim.category+' - '+fmtDate(claim.receipt_date), isImage:isImageName(claim.receipt_name), name:claim.receipt_name};
      render();
    });
  }

  // Makes a Storage object name safe and readable: letters/numbers/dashes
  // only, no run of repeated dashes, nothing leading/trailing.
  function sanitizeForFilename(s){
    return String(s||'').trim().replace(/[^a-zA-Z0-9]+/g,'-').replace(/^-+|-+$/g,'') || 'file';
  }

  function uploadReceipt(file, category, receiptDate){
    var ext = (file.name.split('.').pop()||'bin').toLowerCase();
    // The FOLDER stays keyed by the employee's auth id - that's what the
    // receipts_* Storage policies check to enforce "only this employee or
    // an admin can see this file", and ids are stable/unique in a way a
    // name never is (two employees can share a name, and a name can be
    // corrected later). The FILENAME, though, is just for humans browsing
    // Storage directly during an audit - so it leads with the employee's
    // name, then the receipt date and category, so a folder's contents are
    // self-explanatory without having to open the app or match the file to
    // a claims row first.
    var namePart = sanitizeForFilename(STATE.profile && STATE.profile.name);
    var datePart = sanitizeForFilename(receiptDate || new Date().toISOString().slice(0,10));
    var catPart = sanitizeForFilename(category);
    var uniquePart = Date.now() + '-' + Math.random().toString(36).slice(2,8);
    var filename = [namePart, datePart, catPart, uniquePart].filter(Boolean).join('_') + '.' + ext;
    var path = STATE.session.user.id + '/' + filename;
    return withNetworkRetry(function(){ return supabase.storage.from('receipts').upload(path, file); }).then(function(res){
      if(res.error) throw res.error;
      return {path:path, name:file.name};
    });
  }

  function submitClaim(form){
    var category = form.category.value;
    var vendor = form.vendor.value.trim();
    var currency = form.currency.value || 'SGD';
    var amount = parseFloat(form.amount.value);
    var receiptDate = form.receiptDate.value;
    var file = form.receipt.files[0];
    var familyMemberIdField = form.querySelector('[name="familyMemberId"]');
    var familyMemberId = familyMemberIdField ? (familyMemberIdField.value || null) : null;
    if(!category || !vendor || !amount || amount<=0 || !receiptDate || !file){ showToast('Please complete all fields.', 'error'); return Promise.resolve(); }
    if(file.size > 4*1024*1024){ showToast('File too large - please upload a file under 4MB.', 'error'); return Promise.resolve(); }

    var currentBY = currentBenefitYear();
    var receiptBY = benefitYearForDate(receiptDate);
    if(receiptBY !== currentBY){
      STATE.claimFormError = 'This receipt is dated '+fmtDate(receiptDate)+', which falls outside the current benefit year. Only receipts from '+fmtDateDMY(yearStartStr())+' onward can be claimed this cycle - your benefits reset every '+benefitYearResetLabel()+'.';
      render();
      return Promise.resolve();
    }

    var btn = form.querySelector('button[type=submit]');
    btn.disabled = true; btn.textContent = 'Checking exchange rate...';

    return getExchangeRateToSGD(currency).then(function(rate){
      var amountSgd = Math.round(amount*rate*100)/100;
      var wallet = computeWallet(STATE.profile.id);
      if(amountSgd > wallet.available){
        STATE.claimFormError = 'This comes to '+fmtMoney(amountSgd)+' SGD, which is more than your available balance of '+fmtMoney(wallet.available)+'.';
        render();
        return null;
      }
      STATE.claimFormError = null;
      btn.textContent = 'Uploading...';
      return uploadReceipt(file, category, receiptDate).then(function(receipt){
        return withNetworkRetry(function(){
          return supabase.from('claims').insert({
            employee_id: STATE.session.user.id, category:category, vendor:vendor,
            amount:amount, currency:currency, amount_sgd:amountSgd, exchange_rate:rate,
            receipt_date:receiptDate, receipt_path:receipt.path, receipt_name:receipt.name, status:'pending',
            family_member_id: familyMemberId
          });
        });
      });
    }).then(function(res){
      if(res===null) return;
      if(res.error) throw res.error;
      showToast('Claim submitted successfully and is pending review.', 'success');
      STATE.activeTab = 'history';
      return loadAppData();
    }).then(function(){ render(); }).catch(function(err){
      console.error(err);
      showToast('Something went wrong: '+(err.message||err), 'error');
      render();
    });
  }

  function approveClaim(id){
    return supabase.from('claims').update({status:'approved', decided_at:new Date().toISOString()}).eq('id', id).then(function(res){
      if(res.error){ showToast('Could not approve claim: '+res.error.message, 'error'); return; }
      showToast('Claim approved.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  function confirmReject(id){
    var reasonSel = document.querySelector('[data-field="reject-reason-'+id+'"]');
    var noteInput = document.querySelector('[data-field="reject-note-'+id+'"]');
    var otherInput = document.querySelector('[data-field="reject-other-'+id+'"]');
    var reason = reasonSel ? reasonSel.value : '';
    if(!reason){ showToast('Please select a rejection reason.', 'error'); return Promise.resolve(); }
    if(reason==='Others'){
      var customReason = otherInput ? otherInput.value.trim() : '';
      if(!customReason){ showToast('Please specify a reason.', 'error'); return Promise.resolve(); }
      reason = customReason;
    }
    var note = noteInput ? noteInput.value.trim() : '';
    return supabase.from('claims').update({status:'rejected', reject_reason:reason, admin_note:note, decided_at:new Date().toISOString()}).eq('id', id).then(function(res){
      if(res.error){ showToast('Could not reject claim: '+res.error.message, 'error'); return; }
      STATE.rejectingClaimId = null;
      showToast('Claim rejected and employee notified.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  function markNotificationRead(id){
    return supabase.from('notifications').update({read:true}).eq('id', id).then(function(res){
      if(res.error) return;
      return loadAppData();
    }).then(function(){ render(); });
  }

  function confirmEditClaim(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    if(!claim) return Promise.resolve();
    if(claim.employee_id !== STATE.session.user.id){ showToast('You can only edit your own claims.', 'error'); return Promise.resolve(); }
    if(claim.status==='approved'){ showToast('Approved claims cannot be edited.', 'error'); return Promise.resolve(); }

    var catSel = document.getElementById('edit-category-'+id);
    var vendorInput = document.getElementById('edit-vendor-'+id);
    var currencySel = document.getElementById('edit-currency-'+id);
    var amtInput = document.getElementById('edit-amount-'+id);
    var dateInput = document.getElementById('edit-date-'+id);
    var fileInput = document.getElementById('edit-receipt-'+id);
    var familySel = document.getElementById('edit-family-'+id);
    var category = catSel ? catSel.value : claim.category;
    var vendor = vendorInput ? vendorInput.value.trim() : claim.vendor;
    var currency = currencySel ? currencySel.value : (claim.currency||'SGD');
    var amount = amtInput ? parseFloat(amtInput.value) : claim.amount;
    var receiptDate = dateInput ? dateInput.value : claim.receipt_date;
    var familyMemberId = familySel ? (familySel.value || null) : claim.family_member_id;
    if(!category || !vendor || !amount || amount<=0 || !receiptDate){ showToast('Please complete all fields.', 'error'); return Promise.resolve(); }

    var currentBY = currentBenefitYear();
    var receiptBY = benefitYearForDate(receiptDate);
    if(receiptBY !== currentBY){
      STATE.claimFormError = 'This receipt is dated '+fmtDate(receiptDate)+', which falls outside the current benefit year. Only receipts from '+fmtDateDMY(yearStartStr())+' onward can be claimed this cycle - your benefits reset every '+benefitYearResetLabel()+'.';
      render();
      return Promise.resolve();
    }

    var file = fileInput && fileInput.files && fileInput.files[0];
    var wasRejected = claim.status === 'rejected';

    return getExchangeRateToSGD(currency).then(function(rate){
      var amountSgd = Math.round(amount*rate*100)/100;
      var wallet = computeWallet(STATE.profile.id);
      var availableForThisEdit = claim.status==='pending' ? wallet.available + sgdAmountOf(claim) : wallet.available;
      if(amountSgd > availableForThisEdit){
        STATE.claimFormError = 'This comes to '+fmtMoney(amountSgd)+' SGD, which is more than your available balance of '+fmtMoney(availableForThisEdit)+'.';
        render();
        return null;
      }
      STATE.claimFormError = null;

      var updates = {category:category, vendor:vendor, currency:currency, amount:amount, amount_sgd:amountSgd, exchange_rate:rate, receipt_date:receiptDate, last_edited_at:new Date().toISOString(), family_member_id:familyMemberId};
      if(wasRejected){ updates.status='pending'; updates.reject_reason=null; updates.admin_note=null; updates.decided_at=null; }

      function applyUpdate(){
        return supabase.from('claims').update(updates).eq('id', id).then(function(res){
          if(res.error){ showToast('Could not save changes: '+res.error.message, 'error'); return; }
          STATE.editingClaimId = null;
          showToast(wasRejected ? 'Claim updated and resubmitted for review.' : 'Claim updated.', 'success');
          return loadAppData();
        }).then(function(){ render(); });
      }

      if(file){
        if(file.size > 4*1024*1024){ showToast('File too large - please upload a file under 4MB.', 'error'); return null; }
        return uploadReceipt(file, category, receiptDate).then(function(receipt){
          updates.receipt_path = receipt.path; updates.receipt_name = receipt.name;
          return applyUpdate();
        }).catch(function(err){ showToast('Upload failed: '+(err.message||err), 'error'); });
      }
      return applyUpdate();
    }).catch(function(err){
      console.error(err);
      showToast('Could not fetch the exchange rate: '+(err.message||err), 'error');
    });
  }

  function deleteClaimConfirmed(id){
    var claim = STATE.claims.filter(function(c){ return c.id===id; })[0];
    STATE.confirmDeleteClaimId = null;
    if(!claim){ render(); return Promise.resolve(); }
    if(claim.employee_id !== STATE.session.user.id){ showToast('You can only delete your own claims.', 'error'); render(); return Promise.resolve(); }
    if(claim.status==='approved'){ showToast('Approved claims cannot be deleted.', 'error'); render(); return Promise.resolve(); }
    return supabase.from('claims').delete().eq('id', id).then(function(res){
      if(res.error){ showToast('Could not delete claim: '+res.error.message, 'error'); return; }
      showToast('Claim deleted.', 'success');
      return loadAppData();
    }).then(function(){ render(); });
  }

  /* =========================================================
     ACTION HANDLERS - ADMIN: STAFF / INVITES / BENEFITS / ACCESS
  ========================================================== */
  function inviteStaff(form){
    var name = form.name.value.trim();
    var email = form.email.value.trim().toLowerCase();
    var dateOfEmployment = form.dateOfEmployment.value;
    var effectiveDate = form.effectiveDate.value;
    var paynowMobile = form.paynowMobile.value.trim();
    var nric = form.nric.value.trim();
    var allocRaw = form.annualAllocation.value;
    var alloc = parseFloat(allocRaw);
    var prorateEntitlement = !!(form.prorateEntitlement && form.prorateEntitlement.checked);
    if(!name || !email || !dateOfEmployment || !effectiveDate || !paynowMobile || allocRaw==='' || isNaN(alloc)){
      showToast('Please complete all fields before adding the employee.', 'error');
      return Promise.resolve();
    }

    var familyRows = [];
    if(STATE.addEmployeeMode==='family'){
      var rowEls = form.querySelectorAll('.family-draft-row');
      for(var i=0;i<rowEls.length;i++){
        var rowEl = rowEls[i];
        var famName = rowEl.querySelector('[name="famName[]"]').value.trim();
        var famRel = rowEl.querySelector('[name="famRelationship[]"]').value;
        var famDob = rowEl.querySelector('[name="famDob[]"]').value;
        var famNric = rowEl.querySelector('[name="famNric[]"]').value.trim();
        if(!famName && !famRel && !famDob && !famNric) continue;
        if(!famName || !famRel || !famDob){
          showToast('Please complete name, relationship and date of birth for each family member (or remove the blank row).', 'error');
          return Promise.resolve();
        }
        familyRows.push({employee_email:email, name:famName, relationship:famRel, date_of_birth:famDob, nric: famNric || null});
      }
    }

    return supabase.from('invites').upsert(
      {email:email, name:name, role:'user', annual_allocation:alloc, date_of_joining:dateOfEmployment, paynow_mobile:paynowMobile, effective_date:effectiveDate, nric: nric || null, welcome_email_sent:false, invited_by:STATE.session.user.id, used:false, prorate_entitlement_default:prorateEntitlement},
      {onConflict:'email'}
    ).then(function(res){
      if(res.error) throw new Error('Could not add employee: '+res.error.message);
      if(!familyRows.length) return null;
      return supabase.from('family_members').insert(familyRows).then(function(res2){
        if(res2.error) throw new Error('Employee added, but could not add family members: '+res2.error.message);
      });
    }).then(function(){
      showToast('Added '+name+(familyRows.length?(' with '+familyRows.length+' family member'+(familyRows.length>1?'s':'')):'')+'.', 'success');
      form.reset();
      STATE.addEmployeeMode = 'single';
      return loadAppData();
    }).then(function(){ render(); }).catch(function(err){
      showToast(err.message||String(err), 'error');
      render();
    });
  }

  function handleEmployeeCsv(file){
    if(!file) return Promise.resolve();
    return file.text().then(function(text){
      var lines = text.split(/\r?\n/).map(function(l){ return l.trim(); }).filter(Boolean);
      if(lines.length<2){ showToast('CSV appears to be empty.', 'error'); return; }

      var knownEmails = {};
      STATE.profiles.forEach(function(p){ knownEmails[(p.email||'').toLowerCase()] = true; });
      STATE.invites.forEach(function(inv){ knownEmails[(inv.email||'').toLowerCase()] = true; });
      for(var pass=1; pass<lines.length; pass++){
        var pparts = lines[pass].split(',').map(function(p){ return p.trim(); });
        if((pparts[0]||'').toLowerCase()==='employee' && pparts[2]){ knownEmails[pparts[2].toLowerCase()] = true; }
      }

      var inviteRows = [];
      var familyRows = [];
      var skipped = 0;
      for(var i=1;i<lines.length;i++){
        var parts = lines[i].split(',').map(function(p){ return p.trim(); });
        var recordType = (parts[0]||'').toLowerCase();
        var name = parts[1];
        var email = (parts[2]||'').toLowerCase();
        if(recordType==='family'){
          var relationship = parts[3];
          var dateOfBirth = parts[4] && parts[4].length ? parts[4] : null;
          var nric = parts[5] && parts[5].length ? parts[5] : null;
          if(!name || !email || !relationship || !dateOfBirth || !knownEmails[email]){ skipped++; continue; }
          familyRows.push({employee_email:email, name:name, relationship:relationship, date_of_birth:dateOfBirth, nric:nric});
        } else if(recordType==='employee'){
          var nric2 = parts[5] && parts[5].length ? parts[5] : null;
          var alloc = parseFloat(parts[6])||1000;
          var dateOfJoining = parts[7] && parts[7].length ? parts[7] : null;
          var paynowMobile = parts[8] && parts[8].length ? parts[8] : null;
          var effectiveDate = parts[9] && parts[9].length ? parts[9] : null;
          // Optional 11th column: prorateEntitlement (Yes/No) pre-sets the
          // New Hire Invoicing tab's "Prorate" checkbox default for this
          // employee. Left blank, defaults to true (prorated) - same as the
          // checkbox's own default.
          var prorateRaw = parts[10] && parts[10].length ? parts[10] : null;
          var prorateEntitlementDefault = prorateRaw==null ? true : /^y/i.test(prorateRaw);
          if(!name || !email){ skipped++; continue; }
          inviteRows.push({email:email, name:name, role:'user', annual_allocation:alloc, date_of_joining:dateOfJoining, paynow_mobile:paynowMobile, effective_date:effectiveDate, nric:nric2, welcome_email_sent:false, invited_by:STATE.session.user.id, used:false, prorate_entitlement_default:prorateEntitlementDefault});
        } else {
          skipped++;
        }
      }
      if(!inviteRows.length && !familyRows.length){ showToast('No valid rows found in that CSV.', 'error'); return; }

      var chain = Promise.resolve();
      if(inviteRows.length){
        chain = chain.then(function(){ return supabase.from('invites').upsert(inviteRows, {onConflict:'email'}); }).then(function(res){
          if(res.error) throw new Error('Employee rows failed: '+res.error.message);
        });
      }
      if(familyRows.length){
        chain = chain.then(function(){ return supabase.from('family_members').insert(familyRows); }).then(function(res){
          if(res.error) throw new Error('Family rows failed: '+res.error.message);
        });
      }
      return chain.then(function(){
        var parts2 = [];
        if(inviteRows.length) parts2.push(inviteRows.length+' employee(s)');
        if(familyRows.length) parts2.push(familyRows.length+' family member(s)');
        showToast(parts2.join(' and ')+' added.'+(skipped?(' '+skipped+' row(s) skipped.'):''), 'success');
        return loadAppData();
      });
    }).then(function(){ render(); }).catch(function(err){
      showToast(err && err.message ? err.message : 'Could not read that CSV file.', 'error');
      render();
    });
  }

